import { describe, expect, it } from 'vitest';
import { generateFloor, roomAt, roomCentrePx, type FloorMap } from '../../src/sim/dungeon';
import { Tile, TILE_SIZE } from '../../src/sim/tiles';

/** Tiles reachable on foot from the start room centre, with every door open. */
function reachable(floor: FloorMap): Set<number> {
  const { grid } = floor;
  const start = roomCentrePx(floor.rooms[floor.startRoom]);
  const sx = Math.floor(start.x / TILE_SIZE);
  const sy = Math.floor(start.y / TILE_SIZE);
  const seen = new Set([grid.index(sx, sy)]);
  const stack = [[sx, sy]];
  while (stack.length > 0) {
    const [x, y] = stack.pop()!;
    for (const [dx, dy] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ]) {
      const nx = x + dx;
      const ny = y + dy;
      const i = grid.index(nx, ny);
      if (!grid.isWalkable(nx, ny) || seen.has(i)) continue;
      seen.add(i);
      stack.push([nx, ny]);
    }
  }
  return seen;
}

const SEEDS = [1, 2, 3, 42, 1337, 98765, 4242424];

describe('dungeon generation', () => {
  it('is deterministic for a seed', () => {
    const a = generateFloor(77, 0, { roomCount: 8 });
    const b = generateFloor(77, 0, { roomCount: 8 });
    expect(Array.from(a.grid.tiles)).toEqual(Array.from(b.grid.tiles));
    expect(a.rooms.map((r) => r.kind)).toEqual(b.rooms.map((r) => r.kind));
  });

  it('differs between seeds', () => {
    const a = generateFloor(1, 0, { roomCount: 8 });
    const b = generateFloor(2, 0, { roomCount: 8 });
    expect(Array.from(a.grid.tiles)).not.toEqual(Array.from(b.grid.tiles));
  });

  it.each(SEEDS)('connects every walkable tile to the start (seed %i)', (seed) => {
    const floor = generateFloor(seed, 2, { roomCount: 9 });
    const seen = reachable(floor);
    let walkable = 0;
    for (let y = 0; y < floor.grid.height; y++)
      for (let x = 0; x < floor.grid.width; x++) if (floor.grid.isWalkable(x, y)) walkable++;
    expect(seen.size).toBe(walkable);
  });

  it.each(SEEDS)('has one start, one boss, one treasure room (seed %i)', (seed) => {
    const floor = generateFloor(seed, 0, { roomCount: 8 });
    const count = (kind: string): number => floor.rooms.filter((r) => r.kind === kind).length;
    expect(floor.rooms).toHaveLength(8);
    expect(count('start')).toBe(1);
    expect(count('boss')).toBe(1);
    expect(count('treasure')).toBe(1);
    expect(floor.rooms[floor.bossRoom].kind).toBe('boss');
    const maxDistance = Math.max(...floor.rooms.map((r) => r.distance));
    expect(floor.rooms[floor.bossRoom].distance).toBe(maxDistance);
  });

  it('encloses every walkable tile with walls (no walkable tile touches void)', () => {
    for (const seed of SEEDS) {
      const { grid } = generateFloor(seed, 1, { roomCount: 10 });
      for (let y = 0; y < grid.height; y++)
        for (let x = 0; x < grid.width; x++) {
          if (!grid.isWalkable(x, y)) continue;
          for (const [dx, dy] of [
            [1, 0],
            [-1, 0],
            [0, 1],
            [0, -1],
          ])
            expect(grid.get(x + dx, y + dy)).not.toBe(Tile.Void);
        }
    }
  });

  it('gives each doorway three door tiles that sit on the room wall line', () => {
    const floor = generateFloor(5, 0, { roomCount: 8 });
    for (const room of floor.rooms) {
      expect(room.doors.length).toBeGreaterThan(0);
      for (const door of room.doors) {
        expect(door.tiles).toHaveLength(3);
        for (const t of door.tiles) expect(floor.grid.get(t.x, t.y)).toBe(Tile.Door);
      }
    }
  });

  it('builds the finale as a straight line ending in the boss arena', () => {
    const floor = generateFloor(9, 5, { roomCount: 5, finale: true });
    expect(floor.rooms).toHaveLength(5);
    expect(floor.rooms[floor.bossRoom].distance).toBe(4);
    expect(floor.rooms.filter((r) => r.kind === 'treasure')).toHaveLength(0);
  });

  it('locates the room under a pixel', () => {
    const floor = generateFloor(3, 0, { roomCount: 7 });
    const boss = floor.rooms[floor.bossRoom];
    const c = roomCentrePx(boss);
    expect(roomAt(floor, c.x, c.y)?.id).toBe(boss.id);
    expect(roomAt(floor, 0, 0)).toBeUndefined();
  });
});

import { describe, expect, it } from 'vitest';
import { hasLineOfSight, moveAndCollide, separate } from '../../src/sim/physics';
import { Tile, TileGrid, TILE_SIZE } from '../../src/sim/tiles';
import { Rng, floorSeed } from '../../src/sim/rng';

/** 10x10 floor with a wall column at x = 5. */
function arena(): TileGrid {
  const grid = new TileGrid(10, 10);
  for (let y = 0; y < 10; y++)
    for (let x = 0; x < 10; x++) {
      const edge = x === 0 || y === 0 || x === 9 || y === 9;
      grid.set(x, y, edge || x === 5 ? Tile.Wall : Tile.Floor);
    }
  return grid;
}

describe('moveAndCollide', () => {
  it('stops flush against a wall', () => {
    const grid = arena();
    const body = { x: 3 * TILE_SIZE, y: 3 * TILE_SIZE, radius: 10 };
    const hit = moveAndCollide(grid, body, 200, 0);
    expect(hit).toBe(true);
    expect(body.x + body.radius).toBeLessThanOrEqual(5 * TILE_SIZE);
    expect(body.x + body.radius).toBeGreaterThan(5 * TILE_SIZE - 1);
  });

  it('never tunnels through a one-tile wall at dash speed', () => {
    const grid = arena();
    const body = { x: 4 * TILE_SIZE, y: 4 * TILE_SIZE, radius: 8 };
    moveAndCollide(grid, body, 1000, 0);
    expect(body.x).toBeLessThan(5 * TILE_SIZE);
  });

  it('slides along a wall when moving diagonally', () => {
    const grid = arena();
    const body = { x: 4.5 * TILE_SIZE, y: 3 * TILE_SIZE, radius: 10 };
    moveAndCollide(grid, body, 40, 40);
    expect(body.y).toBeCloseTo(3 * TILE_SIZE + 40, 5);
  });

  it('treats a locked door as solid and an open one as floor', () => {
    const grid = arena();
    grid.set(5, 4, Tile.Door);
    grid.setDoorLocked(5, 4, true);
    const body = { x: 4 * TILE_SIZE, y: 4.5 * TILE_SIZE, radius: 8 };
    moveAndCollide(grid, body, 100, 0);
    expect(body.x).toBeLessThan(5 * TILE_SIZE);
    grid.setDoorLocked(5, 4, false);
    moveAndCollide(grid, body, 100, 0);
    expect(body.x).toBeGreaterThan(6 * TILE_SIZE);
  });
});

describe('separate', () => {
  it('pushes overlapping bodies apart', () => {
    const grid = arena();
    const a = { x: 100, y: 100, radius: 10 };
    const b = { x: 105, y: 100, radius: 10 };
    separate(grid, a, b);
    expect(Math.hypot(b.x - a.x, b.y - a.y)).toBeCloseTo(20, 3);
  });
});

describe('hasLineOfSight', () => {
  it('is blocked by walls', () => {
    const grid = arena();
    expect(hasLineOfSight(grid, 64, 64, 64, 250)).toBe(true);
    expect(hasLineOfSight(grid, 64, 64, 250, 64)).toBe(false);
  });
});

describe('Rng', () => {
  it('replays the same sequence from a seed', () => {
    const a = new Rng(123);
    const b = new Rng(123);
    expect([a.next(), a.int(1, 6), a.range(2, 3)]).toEqual([b.next(), b.int(1, 6), b.range(2, 3)]);
  });

  it('keeps int within inclusive bounds', () => {
    const rng = new Rng(9);
    for (let i = 0; i < 500; i++) {
      const v = rng.int(-2, 2);
      expect(v).toBeGreaterThanOrEqual(-2);
      expect(v).toBeLessThanOrEqual(2);
    }
  });

  it('derives distinct floor seeds per depth', () => {
    const seeds = new Set([0, 1, 2, 3, 4, 5].map((d) => floorSeed(777, d)));
    expect(seeds.size).toBe(6);
  });
});

import { describe, expect, it } from 'vitest';
import {
  CORE_MEMORIES,
  FLOOR_PLANS,
  MEMORY_FRAGMENTS,
  biomeInfo,
  enemyDef,
  fragmentsForFloor,
} from '../../src/sim/content';
import spriteAtlas from '../../src/data/sprite_atlas.json';

describe('content', () => {
  it('resolves every roster and boss in the floor plan', () => {
    for (const plan of FLOOR_PLANS) {
      expect(biomeInfo(plan.biome).name.length).toBeGreaterThan(0);
      for (const id of plan.roster) expect(enemyDef(id).archetype).not.toBe('boss');
      expect(enemyDef(plan.boss, true).archetype).toBe('boss');
    }
  });

  it('maps every enemy to a sprite in the atlas', () => {
    const keys = Object.keys(spriteAtlas.enemies);
    for (const plan of FLOOR_PLANS)
      for (const id of [...plan.roster, plan.boss]) expect(keys).toContain(enemyDef(id).sprite);
  });

  it('makes bosses tougher than their data record', () => {
    expect(enemyDef('guardian', true).maxHealth).toBeGreaterThan(enemyDef('guardian').maxHealth);
  });

  it('only references fragments that exist', () => {
    const ids = new Set(MEMORY_FRAGMENTS.map((f) => f.id));
    for (const core of CORE_MEMORIES) for (const f of core.fragments) expect(ids.has(f)).toBe(true);
  });

  it('offers a floor its own biome fragments first and skips owned ones', () => {
    const first = fragmentsForFloor('ruins', new Set());
    expect(MEMORY_FRAGMENTS.find((f) => f.id === first[0])?.biome).toBe('ruins');
    const owned = new Set(first.slice(0, 1));
    expect(fragmentsForFloor('ruins', owned)).not.toContain(first[0]);
  });

  it('rejects unknown ids with a clear error', () => {
    expect(() => enemyDef('nope')).toThrow(/Unknown enemy id 'nope'/);
  });
