/**
 * Upgrades offered on level-up, from chests and at shrines.
 *
 * A player's stats are always recomputed from the base values plus the count
 * of each upgrade taken, so a save only needs the counts.
 */
import type { Rng } from './rng';

export type Rarity = 'common' | 'rare' | 'epic';

export interface PlayerStats {
  maxHealth: number;
  maxMana: number;
  /** Mana per second. */
  manaRegen: number;
  /** Pixels per second. */
  moveSpeed: number;
  meleeDamage: number;
  /** Swing speed multiplier. */
  attackSpeed: number;
  critChance: number;
  critMultiplier: number;
  dashCharges: number;
  /** Seconds to recharge one dash. */
  dashRecharge: number;
  dashStrike: boolean;
  boltDamage: number;
  boltCost: number;
  boltCount: number;
  boltPierce: number;
  /** Fraction of melee damage healed. */
  lifesteal: number;
  /** Fraction of incoming damage ignored, capped below 1. */
  damageReduction: number;
  pickupRadius: number;
  maxPotions: number;
  shockwave: boolean;
  manaOnKill: number;
}

export const BASE_STATS: Readonly<PlayerStats> = {
  maxHealth: 100,
  maxMana: 60,
  manaRegen: 5,
  moveSpeed: 175,
  meleeDamage: 16,
  attackSpeed: 1,
  critChance: 0.05,
  critMultiplier: 1.75,
  dashCharges: 2,
  dashRecharge: 1.1,
  dashStrike: false,
  boltDamage: 14,
  boltCost: 18,
  boltCount: 1,
  boltPierce: 0,
  lifesteal: 0,
  damageReduction: 0,
  pickupRadius: 64,
  maxPotions: 3,
  shockwave: false,
  manaOnKill: 0,
};

export interface UpgradeDef {
  id: string;
  name: string;
  description: string;
  rarity: Rarity;
  /** Times it can be taken; offers skip maxed upgrades. */
  maxStacks: number;
  apply(stats: PlayerStats): void;
}

export const UPGRADES: readonly UpgradeDef[] = [
  { id: 'vitality', name: 'Vitality', description: '+20 max health', rarity: 'common', maxStacks: 8, apply: (s) => void (s.maxHealth += 20) },
  { id: 'edge', name: 'Keen Edge', description: '+18% melee damage', rarity: 'common', maxStacks: 8, apply: (s) => void (s.meleeDamage *= 1.18) },
  { id: 'haste', name: 'Quickened Arm', description: '+12% attack speed', rarity: 'common', maxStacks: 5, apply: (s) => void (s.attackSpeed *= 1.12) },
  { id: 'swift', name: 'Fleet Step', description: '+8% move speed', rarity: 'common', maxStacks: 4, apply: (s) => void (s.moveSpeed *= 1.08) },
  { id: 'precision', name: 'Precision', description: '+8% critical chance', rarity: 'common', maxStacks: 5, apply: (s) => void (s.critChance += 0.08) },
  { id: 'brutal', name: 'Brutality', description: '+40% critical damage', rarity: 'rare', maxStacks: 3, apply: (s) => void (s.critMultiplier += 0.4) },
  { id: 'flow', name: 'Mana Flow', description: '+15 max mana, +40% mana regen', rarity: 'common', maxStacks: 4, apply: (s) => { s.maxMana += 15; s.manaRegen *= 1.4; } },
  { id: 'bolt_power', name: 'Focused Bolt', description: '+35% bolt damage', rarity: 'common', maxStacks: 5, apply: (s) => void (s.boltDamage *= 1.35) },
  { id: 'bolt_split', name: 'Split Bolt', description: 'Bolts fire one extra projectile', rarity: 'rare', maxStacks: 2, apply: (s) => void (s.boltCount += 1) },
  { id: 'bolt_pierce', name: 'Piercing Bolt', description: 'Bolts pass through one more enemy', rarity: 'rare', maxStacks: 3, apply: (s) => void (s.boltPierce += 1) },
  { id: 'guard', name: 'Stone Skin', description: 'Take 10% less damage', rarity: 'rare', maxStacks: 4, apply: (s) => void (s.damageReduction = Math.min(0.6, s.damageReduction + 0.1)) },
  { id: 'leech', name: 'Memory Leech', description: 'Heal 4% of melee damage dealt', rarity: 'rare', maxStacks: 3, apply: (s) => void (s.lifesteal += 0.04) },
  { id: 'dash_charge', name: 'Second Step', description: '+1 dash charge', rarity: 'rare', maxStacks: 2, apply: (s) => void (s.dashCharges += 1) },
  { id: 'magnet', name: 'Attunement', description: '+60% pickup radius, dashes recharge 15% faster', rarity: 'common', maxStacks: 3, apply: (s) => { s.pickupRadius *= 1.6; s.dashRecharge *= 0.85; } },
  { id: 'flask', name: 'Deep Flask', description: '+1 potion capacity', rarity: 'common', maxStacks: 3, apply: (s) => void (s.maxPotions += 1) },
  { id: 'surge', name: 'Soul Surge', description: 'Kills restore 6 mana', rarity: 'common', maxStacks: 3, apply: (s) => void (s.manaOnKill += 6) },
  { id: 'dash_strike', name: 'Phantom Rush', description: 'Dashing through enemies damages them', rarity: 'epic', maxStacks: 1, apply: (s) => void (s.dashStrike = true) },
  { id: 'shockwave', name: 'Echo Strike', description: 'The third combo hit releases a shockwave', rarity: 'epic', maxStacks: 1, apply: (s) => void (s.shockwave = true) },
];

const BY_ID = new Map(UPGRADES.map((u) => [u.id, u]));

export function upgradeDef(id: string): UpgradeDef {
  const def = BY_ID.get(id);
  if (!def) throw new Error(`Unknown upgrade '${id}'`);
  return def;
}

export function computeStats(taken: Readonly<Record<string, number>>): PlayerStats {
  const stats: PlayerStats = { ...BASE_STATS };
  for (const def of UPGRADES) {
    const count = Math.min(taken[def.id] ?? 0, def.maxStacks);
    for (let i = 0; i < count; i++) def.apply(stats);
  }
  return stats;
}

const RARITY_WEIGHTS: Record<'normal' | 'generous', Record<Rarity, number>> = {
  normal: { common: 64, rare: 28, epic: 8 },
  generous: { common: 30, rare: 50, epic: 20 },
};

/** Up to `count` distinct, non-maxed upgrade ids, weighted by rarity. */
export function rollChoices(
  rng: Rng,
  taken: Readonly<Record<string, number>>,
  count = 3,
  luck: 'normal' | 'generous' = 'normal'
): string[] {
  const pool = UPGRADES.filter((u) => (taken[u.id] ?? 0) < u.maxStacks);
  const weights = RARITY_WEIGHTS[luck];
  const picked: string[] = [];
  while (picked.length < count && pool.length > 0) {
    const total = pool.reduce((sum, u) => sum + weights[u.rarity], 0);
    let roll = rng.next() * total;
    let index = 0;
    for (; index < pool.length - 1; index++) {
      roll -= weights[pool[index].rarity];
      if (roll < 0) break;
    }
    picked.push(pool[index].id);
    pool.splice(index, 1);
  }
  return picked;
}

/**
 * Plain-data entity records. Everything here is JSON-serializable so a world
 * can be inspected or snapshotted without custom code.
 */
import type { EnemyDef } from './content';
import type { PlayerStats } from './upgrades';

export type PlayerAction = 'idle' | 'move' | 'attack' | 'dash' | 'dead';

export interface Player {
  x: number;
  y: number;
  radius: number;
  /** Aim angle in radians; also the facing used for sprites. */
  aim: number;
  action: PlayerAction;
  health: number;
  mana: number;
  stats: PlayerStats;
  /** Upgrade id -> times taken. */
  upgrades: Record<string, number>;
  level: number;
  xp: number;
  shards: number;
  potions: number;
  /** Dash charges, fractional while recharging. */
  dashCharges: number;
  /** Combo step of the current or last swing (0..2). */
  combo: number;
  /** Seconds into the current swing; -1 when not swinging. */
  swingTime: number;
  swingDuration: number;
  swingHitDone: boolean;
  /** Seconds left in which the next swing continues the combo. */
  comboWindow: number;
  dashTime: number;
  dashDirX: number;
  dashDirY: number;
  /** Enemies already hit by the current dash (Phantom Rush). */
  dashHits: number[];
  boltCooldown: number;
  invulnerable: number;
  knockX: number;
  knockY: number;
  /** Seconds the hurt flash shows. */
  hurtFlash: number;
}

export type EnemyState = 'spawning' | 'chase' | 'windup' | 'attack' | 'recover' | 'stagger' | 'dying';

/** Boss and caster attack shapes, also used by the view to draw telegraphs. */
export type AttackKind = 'strike' | 'lunge' | 'slam' | 'shot' | 'spread' | 'ring' | 'charge' | 'volley' | 'summon';

export interface Enemy {
  id: number;
  def: EnemyDef;
  x: number;
  y: number;
  radius: number;
  health: number;
  maxHealth: number;
  state: EnemyState;
  /** Seconds left in the current state. */
  stateTime: number;
  /** Seconds until the next attack may start. */
  cooldown: number;
  attack: AttackKind;
  /** Locked attack direction during windup and attack. */
  dirX: number;
  dirY: number;
  knockX: number;
  knockY: number;
  /** Seconds the white hit flash shows. */
  flash: number;
  roomId: number;
  elite: boolean;
  isBoss: boolean;
  /** Boss phase 0..2, advancing at 60% and 30% health. */
  phase: number;
  /** Index into the boss pattern rotation. */
  patternIndex: number;
  /** Player already hit by this attack, so one swing deals damage once. */
  attackLanded: boolean;
  /** Strafe sign for casters and skirmishers. */
  strafe: number;
}

export type ProjectileOwner = 'player' | 'enemy';

export interface Projectile {
  id: number;
  owner: ProjectileOwner;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  damage: number;
  /** Seconds before it fades. */
  life: number;
  /** Extra enemies it may pass through. */
  pierce: number;
  hitIds: number[];
}

export type PickupKind = 'shard' | 'health' | 'potion' | 'fragment';

export interface Pickup {
  id: number;
  kind: PickupKind;
  x: number;
  y: number;
  amount: number;
  /** Fragment id for kind 'fragment'. */
  fragmentId?: string;
  /** Seconds since dropped; shards scatter briefly before homing. */
  age: number;
  vx: number;
  vy: number;
}

export type InteractableKind = 'chest' | 'shrine' | 'portal';

export interface Interactable {
  id: number;
  kind: InteractableKind;
  x: number;
  y: number;
  used: boolean;
  /** Shards a shrine upgrade costs. */
  cost: number;
}

/** One frame of player intent, produced by the input layer or a test. */
export interface InputFrame {
  /** Movement direction; any length, normalized by the sim. */
  moveX: number;
  moveY: number;
  /** Aim target in world pixels. */
  aimX: number;
  aimY: number;
  attack: boolean;
  bolt: boolean;
  dash: boolean;
  potion: boolean;
  interact: boolean;
}

export const NO_INPUT: Readonly<InputFrame> = {
  moveX: 0,
  moveY: 0,
  aimX: 0,
  aimY: 0,
  attack: false,
  bolt: false,
  dash: false,
  potion: false,
  interact: false,
};

/**
 * Events a world step emits. The view turns them into effects, the audio
 * layer into sounds and the UI into messages; the sim never depends on them.
 */
import type { AttackKind, InteractableKind, PickupKind } from './entities';

export type SimEvent =
  | { type: 'swing'; x: number; y: number; angle: number; combo: number }
  | { type: 'dash'; x: number; y: number }
  | { type: 'bolt'; x: number; y: number; angle: number }
  | { type: 'hit'; x: number; y: number; amount: number; crit: boolean; target: 'enemy' | 'player' }
  | { type: 'shockwave'; x: number; y: number; radius: number }
  | { type: 'enemySpawned'; id: number; x: number; y: number }
  | { type: 'enemyWindup'; id: number; attack: AttackKind }
  | { type: 'enemyAttack'; id: number; attack: AttackKind; x: number; y: number }
  | { type: 'enemyDied'; id: number; x: number; y: number; boss: boolean }
  | { type: 'playerHurt'; amount: number }
  | { type: 'playerDied' }
  | { type: 'potion'; healed: number }
  | { type: 'pickup'; kind: PickupKind; x: number; y: number; amount: number }
  | { type: 'levelUp'; level: number }
  | { type: 'roomLocked'; roomId: number }
  | { type: 'roomCleared'; roomId: number }
  | { type: 'bossIntro'; name: string }
  | { type: 'bossPhase'; phase: number }
  | { type: 'fragmentFound'; fragmentId: string }
  | { type: 'interact'; kind: InteractableKind; x: number; y: number }
  | { type: 'notice'; text: string }
  | { type: 'floorExit' }
  | { type: 'victory' }
  | { type: 'shake'; strength: number };

/**
 * Combat contract shared by the player and enemy logic.
 *
 * `Arena` is what the World exposes to actors; keeping it an interface lets
 * player.ts and enemies.ts stay free of any import of world.ts.
 */
import type { Enemy, Player, Projectile } from './entities';
import type { SimEvent } from './events';
import type { Rng } from './rng';
import type { TileGrid } from './tiles';

export type DamageSource = 'melee' | 'bolt' | 'dash' | 'shockwave';

export interface Arena {
  readonly grid: TileGrid;
  readonly rng: Rng;
  readonly player: Player;
  readonly enemies: readonly Enemy[];
  emit(event: SimEvent): void;
  /** Applies damage, knockback, lifesteal and kill rewards. Returns damage dealt. */
  damageEnemy(enemy: Enemy, amount: number, source: DamageSource, crit: boolean, knockback: number): number;
  /** Applies damage unless the player is invulnerable; knockback points away from (fromX, fromY). */
  damagePlayer(amount: number, fromX: number, fromY: number, knockback: number): void;
  spawnProjectile(projectile: Omit<Projectile, 'id' | 'hitIds'>): void;
  /** Spawns an enemy (with its spawn telegraph) into a room. */
  spawnEnemy(defId: string, x: number, y: number, roomId: number): Enemy;
  /** Freezes the simulation briefly to sell a heavy hit. */
  hitstop(seconds: number): void;
}

export function angleBetween(x0: number, y0: number, x1: number, y1: number): number {
  return Math.atan2(y1 - y0, x1 - x0);
}

/** Smallest signed difference between two angles, in (-PI, PI]. */
export function angleDelta(a: number, b: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d <= -Math.PI) d += Math.PI * 2;
  return d;
}

/**
 * True when a target circle touches the sector at (cx, cy) facing `angle`
 * with the given reach and half-angle. Targets overlapping the origin always count.
 */
export function inArc(
  cx: number,
  cy: number,
  angle: number,
  reach: number,
  halfAngle: number,
  tx: number,
  ty: number,
  targetRadius: number
): boolean {
  const dist = Math.hypot(tx - cx, ty - cy);
  if (dist > reach + targetRadius) return false;
  if (dist <= targetRadius + 4) return true;
  // Widen the arc by the angle the target's radius subtends.
  const slack = Math.asin(Math.min(1, targetRadius / dist));
  return Math.abs(angleDelta(angle, angleBetween(cx, cy, tx, ty))) <= halfAngle + slack;
}

export function circlesTouch(
  ax: number,
  ay: number,
  ar: number,
  bx: number,
  by: number,
  br: number
): boolean {
  const r = ar + br;
  return (bx - ax) * (bx - ax) + (by - ay) * (by - ay) <= r * r;
}

/** Rolls a crit and returns the final damage and whether it critted. */
export function rollDamage(
  rng: Rng,
  base: number,
  critChance: number,
  critMultiplier: number
): { amount: number; crit: boolean } {
  const crit = rng.chance(critChance);
  const spread = rng.range(0.9, 1.1);
  return { amount: Math.max(1, Math.round(base * spread * (crit ? critMultiplier : 1))), crit };
}

/**
 * Player controller: movement, the three-hit combo, dash, bolt and potion.
 */
import { angleBetween, inArc, rollDamage, type Arena } from './combat';
import type { InputFrame, Player } from './entities';
import { moveAndCollide } from './physics';
import { computeStats } from './upgrades';

/** Per combo step: damage multiplier, reach, half-arc (radians), knockback, base duration. */
const COMBO = [
  { damage: 1, reach: 54, halfArc: 1.0, knockback: 150, duration: 0.3 },
  { damage: 1.15, reach: 56, halfArc: 1.0, knockback: 170, duration: 0.3 },
  { damage: 1.8, reach: 64, halfArc: 1.45, knockback: 340, duration: 0.4 },
] as const;
/** Fraction of a swing at which its hit lands. */
const SWING_ACTIVE_AT = 0.38;
const COMBO_GRACE = 0.4;
const DASH_TIME = 0.17;
const DASH_SPEED = 560;
const DASH_IFRAMES = 0.24;
const BOLT_SPEED = 560;
const BOLT_COOLDOWN = 0.3;
const BOLT_SPREAD = 0.2;
const POTION_HEAL = 0.45;
const SHOCKWAVE_RADIUS = 90;

export function createPlayer(x: number, y: number): Player {
  const stats = computeStats({});
  return {
    x,
    y,
    radius: 11,
    aim: 0,
    action: 'idle',
    health: stats.maxHealth,
    mana: stats.maxMana,
    stats,
    upgrades: {},
    level: 1,
    xp: 0,
    shards: 0,
    potions: 2,
    dashCharges: stats.dashCharges,
    combo: 0,
    swingTime: -1,
    swingDuration: 0,
    swingHitDone: false,
    comboWindow: 0,
    dashTime: 0,
    dashDirX: 1,
    dashDirY: 0,
    dashHits: [],
    boltCooldown: 0,
    invulnerable: 0,
    knockX: 0,
    knockY: 0,
    hurtFlash: 0,
  };
}

/** Recomputes stats after an upgrade, keeping health and mana as the same absolute values plus any gain. */
export function refreshStats(player: Player): void {
  const before = player.stats;
  const after = computeStats(player.upgrades);
  player.health = Math.min(after.maxHealth, player.health + Math.max(0, after.maxHealth - before.maxHealth));
  player.mana = Math.min(after.maxMana, player.mana + Math.max(0, after.maxMana - before.maxMana));
  player.dashCharges = Math.min(after.dashCharges, player.dashCharges + Math.max(0, after.dashCharges - before.dashCharges));
  player.stats = after;
}

export function updatePlayer(arena: Arena, input: InputFrame, dt: number): void {
  const p = arena.player;
  if (p.action === 'dead') return;
  const s = p.stats;

  p.invulnerable = Math.max(0, p.invulnerable - dt);
  p.hurtFlash = Math.max(0, p.hurtFlash - dt);
  p.boltCooldown = Math.max(0, p.boltCooldown - dt);
  p.comboWindow = Math.max(0, p.comboWindow - dt);
  p.mana = Math.min(s.maxMana, p.mana + s.manaRegen * dt);
  if (p.dashCharges < s.dashCharges) p.dashCharges = Math.min(s.dashCharges, p.dashCharges + dt / s.dashRecharge);
  p.aim = angleBetween(p.x, p.y, input.aimX, input.aimY);

  let moveX = input.moveX;
  let moveY = input.moveY;
  const len = Math.hypot(moveX, moveY);
  if (len > 1e-6) {
    moveX /= len;
    moveY /= len;
  }

  if (input.potion) drinkPotion(arena);
  if (input.dash && p.dashCharges >= 1 && p.dashTime <= 0) startDash(arena, len > 1e-6 ? moveX : Math.cos(p.aim), len > 1e-6 ? moveY : Math.sin(p.aim));

  if (p.dashTime > 0) {
    updateDash(arena, dt);
    return;
  }

  if (input.bolt) fireBolt(arena);
  if (input.attack && p.swingTime < 0) startSwing(arena);
  if (p.swingTime >= 0) updateSwing(arena, dt);

  const speed = s.moveSpeed * (p.swingTime >= 0 ? 0.4 : 1);
  moveAndCollide(arena.grid, p, (moveX * speed + p.knockX) * dt, (moveY * speed + p.knockY) * dt);
  const decay = Math.exp(-12 * dt);
  p.knockX *= decay;
  p.knockY *= decay;
  if (p.swingTime >= 0) p.action = 'attack';
  else p.action = len > 1e-6 ? 'move' : 'idle';
}

function drinkPotion(arena: Arena): void {
  const p = arena.player;
  if (p.potions <= 0 || p.health >= p.stats.maxHealth) return;
  const healed = Math.min(p.stats.maxHealth - p.health, Math.round(p.stats.maxHealth * POTION_HEAL));
  p.potions--;
  p.health += healed;
  arena.emit({ type: 'potion', healed });
}

function startDash(arena: Arena, dirX: number, dirY: number): void {
  const p = arena.player;
  p.dashCharges -= 1;
  p.dashTime = DASH_TIME;
  p.dashDirX = dirX;
  p.dashDirY = dirY;
  p.dashHits = [];
  p.invulnerable = Math.max(p.invulnerable, DASH_IFRAMES);
  // Dashing cancels a swing; the combo stays alive for a dash-then-strike.
  p.swingTime = -1;
  p.comboWindow = Math.max(p.comboWindow, COMBO_GRACE);
  p.action = 'dash';
  arena.emit({ type: 'dash', x: p.x, y: p.y });
}

function updateDash(arena: Arena, dt: number): void {
  const p = arena.player;
  p.dashTime -= dt;
  p.action = 'dash';
  moveAndCollide(arena.grid, p, p.dashDirX * DASH_SPEED * dt, p.dashDirY * DASH_SPEED * dt);
  if (!p.stats.dashStrike) return;
  for (const enemy of arena.enemies) {
    if (enemy.state === 'spawning' || enemy.state === 'dying' || p.dashHits.includes(enemy.id)) continue;
    if (Math.hypot(enemy.x - p.x, enemy.y - p.y) > enemy.radius + p.radius + 6) continue;
    p.dashHits.push(enemy.id);
    const hit = rollDamage(arena.rng, p.stats.meleeDamage * 0.8, p.stats.critChance, p.stats.critMultiplier);
    arena.damageEnemy(enemy, hit.amount, 'dash', hit.crit, 120);
  }
}

function fireBolt(arena: Arena): void {
  const p = arena.player;
  const s = p.stats;
  if (p.boltCooldown > 0 || p.mana < s.boltCost) return;
  p.mana -= s.boltCost;
  p.boltCooldown = BOLT_COOLDOWN;
  for (let i = 0; i < s.boltCount; i++) {
    const offset = (i - (s.boltCount - 1) / 2) * BOLT_SPREAD;
    const angle = p.aim + offset;
    arena.spawnProjectile({
      owner: 'player',
      x: p.x + Math.cos(angle) * 14,
      y: p.y + Math.sin(angle) * 14,
      vx: Math.cos(angle) * BOLT_SPEED,
      vy: Math.sin(angle) * BOLT_SPEED,
      radius: 6,
      damage: s.boltDamage,
      life: 0.85,
      pierce: s.boltPierce,
    });
  }
  arena.emit({ type: 'bolt', x: p.x, y: p.y, angle: p.aim });
}

function startSwing(arena: Arena): void {
  const p = arena.player;
  p.combo = p.comboWindow > 0 ? (p.combo + 1) % COMBO.length : 0;
  p.swingDuration = COMBO[p.combo].duration / p.stats.attackSpeed;
  p.swingTime = 0;
  p.swingHitDone = false;
  // A small forward step makes each swing feel committed.
  p.knockX += Math.cos(p.aim) * 110;
  p.knockY += Math.sin(p.aim) * 110;
  arena.emit({ type: 'swing', x: p.x, y: p.y, angle: p.aim, combo: p.combo });
}

function updateSwing(arena: Arena, dt: number): void {
  const p = arena.player;
  p.swingTime += dt;
  if (!p.swingHitDone && p.swingTime >= p.swingDuration * SWING_ACTIVE_AT) {
    p.swingHitDone = true;
    resolveSwing(arena);
  }
  if (p.swingTime >= p.swingDuration) {
    p.swingTime = -1;
    p.comboWindow = p.combo === COMBO.length - 1 ? 0 : COMBO_GRACE;
  }
}

function resolveSwing(arena: Arena): void {
  const p = arena.player;
  const step = COMBO[p.combo];
  let landed = 0;
  for (const enemy of arena.enemies) {
    if (enemy.state === 'spawning' || enemy.state === 'dying') continue;
    if (!inArc(p.x, p.y, p.aim, step.reach, step.halfArc, enemy.x, enemy.y, enemy.radius)) continue;
    const hit = rollDamage(arena.rng, p.stats.meleeDamage * step.damage, p.stats.critChance, p.stats.critMultiplier);
    arena.damageEnemy(enemy, hit.amount, 'melee', hit.crit, step.knockback);
    landed++;
  }
  const finisher = p.combo === COMBO.length - 1;
  if (finisher && p.stats.shockwave) {
    const cx = p.x + Math.cos(p.aim) * 30;
    const cy = p.y + Math.sin(p.aim) * 30;
    arena.emit({ type: 'shockwave', x: cx, y: cy, radius: SHOCKWAVE_RADIUS });
    for (const enemy of arena.enemies) {
      if (enemy.state === 'spawning' || enemy.state === 'dying') continue;
      if (Math.hypot(enemy.x - cx, enemy.y - cy) > SHOCKWAVE_RADIUS + enemy.radius) continue;
      arena.damageEnemy(enemy, Math.round(p.stats.meleeDamage * 0.7), 'shockwave', false, 220);
    }
  }
  if (landed > 0) {
    arena.hitstop(finisher ? 0.07 : 0.035);
    arena.emit({ type: 'shake', strength: finisher ? 5 : 2 });
  }
}

/**
 * Enemy behaviour. Every attack has a windup the view telegraphs, then an
 * attack phase, then a recovery window the player can punish. Enemies deal
 * no contact damage; only telegraphed attacks hurt.
 */
import { angleBetween, circlesTouch, inArc, type Arena } from './combat';
import type { EnemyDef } from './content';
import type { AttackKind, Enemy } from './entities';
import { hasLineOfSight, moveAndCollide } from './physics';

/** Windup seconds per attack kind; longer for heavier attacks. */
const WINDUP: Record<AttackKind, number> = {
  strike: 0.42,
  lunge: 0.4,
  slam: 0.75,
  shot: 0.55,
  spread: 0.6,
  ring: 0.7,
  charge: 0.65,
  volley: 0.55,
  summon: 0.8,
};

/** Seconds the attack phase lasts. */
const ACTIVE: Record<AttackKind, number> = {
  strike: 0.15,
  lunge: 0.22,
  slam: 0.12,
  shot: 0.1,
  spread: 0.1,
  ring: 0.1,
  charge: 0.6,
  volley: 0.5,
  summon: 0.1,
};

const BOSS_PATTERNS: Record<string, AttackKind[]> = {
  guardian: ['slam', 'charge', 'spread', 'slam'],
  spirit: ['ring', 'volley', 'summon', 'ring'],
  crystal_golem: ['slam', 'ring', 'charge', 'slam'],
  crystal_guardian: ['charge', 'spread', 'charge', 'ring'],
  forgotten: ['ring', 'summon', 'charge', 'volley'],
  keeper: ['ring', 'charge', 'volley', 'summon', 'slam', 'spread'],
};

/** Boss phase tuning: cooldown factor, ring bullets, bullet speed. */
const PHASES = [
  { cooldown: 1, ring: 10, speed: 170 },
  { cooldown: 0.8, ring: 14, speed: 195 },
  { cooldown: 0.62, ring: 18, speed: 220 },
] as const;

const SPAWN_TIME = 0.7;
const STAGGER_TIME = 0.16;
const DEATH_TIME = 0.5;
const MAX_SUMMONS = 4;

export function createEnemy(
  id: number,
  def: EnemyDef,
  x: number,
  y: number,
  roomId: number,
  scale: { health: number; damage: number },
  elite: boolean
): Enemy {
  const health = Math.round(def.maxHealth * scale.health * (elite ? 1.6 : 1));
  return {
    id,
    def: { ...def, damage: Math.round(def.damage * scale.damage * (elite ? 1.3 : 1)) },
    x,
    y,
    radius: def.radius * (elite ? 1.15 : 1),
    health,
    maxHealth: health,
    state: 'spawning',
    stateTime: SPAWN_TIME,
    cooldown: 0,
    attack: defaultAttack(def),
    dirX: 1,
    dirY: 0,
    knockX: 0,
    knockY: 0,
    flash: 0,
    roomId,
    elite,
    isBoss: def.archetype === 'boss',
    phase: 0,
    patternIndex: 0,
    attackLanded: false,
    strafe: 1,
  };
}

function defaultAttack(def: EnemyDef): AttackKind {
  switch (def.archetype) {
    case 'skirmisher':
      return 'lunge';
    case 'caster':
      return def.behavior === 'splitter' ? 'spread' : 'shot';
    case 'brute':
      return 'slam';
    case 'boss':
      return (BOSS_PATTERNS[def.id] ?? BOSS_PATTERNS.keeper)[0];
    default:
      return 'strike';
  }
}

/** Puts an enemy into its stagger state after a hit (bosses and attackers keep going). */
export function staggerEnemy(enemy: Enemy): void {
  if (enemy.isBoss || enemy.state === 'windup' || enemy.state === 'attack' || enemy.state === 'spawning') return;
  enemy.state = 'stagger';
  enemy.stateTime = STAGGER_TIME;
}

export function killEnemy(enemy: Enemy): void {
  enemy.state = 'dying';
  enemy.stateTime = DEATH_TIME;
}

/** Advances one enemy. Returns false once its death animation has finished. */
export function updateEnemy(arena: Arena, enemy: Enemy, dt: number): boolean {
  enemy.flash = Math.max(0, enemy.flash - dt);
  enemy.cooldown = Math.max(0, enemy.cooldown - dt);
  enemy.stateTime -= dt;
  applyKnockback(arena, enemy, dt);

  switch (enemy.state) {
    case 'spawning':
      if (enemy.stateTime <= 0) {
        enemy.state = 'chase';
        enemy.cooldown = arena.rng.range(0.5, 1.2);
      }
      break;
    case 'dying':
      return enemy.stateTime > 0;
    case 'stagger':
      if (enemy.stateTime <= 0) enemy.state = 'chase';
      break;
    case 'chase':
      chase(arena, enemy, dt);
      break;
    case 'windup':
      windup(arena, enemy);
      break;
    case 'attack':
      attack(arena, enemy, dt);
      break;
    case 'recover':
      if (enemy.stateTime <= 0) enemy.state = 'chase';
      break;
  }
  return true;
}

function applyKnockback(arena: Arena, enemy: Enemy, dt: number): void {
  if (Math.abs(enemy.knockX) + Math.abs(enemy.knockY) < 1) return;
  moveAndCollide(arena.grid, enemy, enemy.knockX * dt, enemy.knockY * dt);
  const decay = Math.exp(-10 * dt);
  enemy.knockX *= decay;
  enemy.knockY *= decay;
}

function step(arena: Arena, enemy: Enemy, dirX: number, dirY: number, speed: number, dt: number): void {
  moveAndCollide(arena.grid, enemy, dirX * speed * dt, dirY * speed * dt);
}

function chase(arena: Arena, enemy: Enemy, dt: number): void {
  const p = arena.player;
  const dx = p.x - enemy.x;
  const dy = p.y - enemy.y;
  const dist = Math.hypot(dx, dy) || 1;
  const nx = dx / dist;
  const ny = dy / dist;
  const def = enemy.def;
  const reach = def.attackRange + p.radius;
  const sight = hasLineOfSight(arena.grid, enemy.x, enemy.y, p.x, p.y);
  if (p.action === 'dead') return;

  switch (def.archetype) {
    case 'caster': {
      // Hold a preferred distance and strafe; back off when crowded.
      const preferred = 190;
      const radial = dist < preferred - 40 ? -1 : dist > preferred + 50 ? 1 : 0;
      if (arena.rng.chance(dt * 0.4)) enemy.strafe *= -1;
      step(arena, enemy, nx * radial - ny * enemy.strafe * 0.7, ny * radial + nx * enemy.strafe * 0.7, def.speed, dt);
      if (enemy.cooldown <= 0 && sight && dist < 380) beginWindup(arena, enemy, defaultAttack(def));
      break;
    }
    case 'skirmisher': {
      // Circle at mid range, then dart in.
      const circling = dist < 150;
      if (arena.rng.chance(dt * 0.5)) enemy.strafe *= -1;
      if (circling) step(arena, enemy, -ny * enemy.strafe, nx * enemy.strafe, def.speed * 0.9, dt);
      else step(arena, enemy, nx, ny, def.speed, dt);
      if (enemy.cooldown <= 0 && sight && dist < 175) beginWindup(arena, enemy, 'lunge');
      break;
    }
    case 'boss': {
      if (dist > 140) step(arena, enemy, nx, ny, def.speed, dt);
      if (enemy.cooldown <= 0) {
        const pattern = BOSS_PATTERNS[def.id] ?? BOSS_PATTERNS.keeper;
        const kind = pattern[enemy.patternIndex % pattern.length];
        enemy.patternIndex++;
        beginWindup(arena, enemy, kind === 'summon' && summonCount(arena, enemy) >= MAX_SUMMONS ? 'ring' : kind);
      }
      break;
    }
    default: {
      // melee and brute walk straight in.
      if (dist > reach * 0.75) step(arena, enemy, nx, ny, def.speed, dt);
      if (enemy.cooldown <= 0 && dist <= reach + (def.archetype === 'brute' ? 30 : 8)) {
        beginWindup(arena, enemy, def.archetype === 'brute' ? 'slam' : 'strike');
      }
    }
  }
}

function summonCount(arena: Arena, boss: Enemy): number {
  return arena.enemies.filter((e) => !e.isBoss && e.roomId === boss.roomId && e.state !== 'dying').length;
}

function beginWindup(arena: Arena, enemy: Enemy, kind: AttackKind): void {
  const p = arena.player;
  const angle = angleBetween(enemy.x, enemy.y, p.x, p.y);
  enemy.state = 'windup';
  enemy.attack = kind;
  enemy.stateTime = WINDUP[kind] * (enemy.isBoss ? Math.max(0.75, PHASES[enemy.phase].cooldown) : 1);
  enemy.dirX = Math.cos(angle);
  enemy.dirY = Math.sin(angle);
  enemy.attackLanded = false;
  arena.emit({ type: 'enemyWindup', id: enemy.id, attack: kind });
}

function windup(arena: Arena, enemy: Enemy): void {
  // Ranged attackers keep tracking until the last moment; melee commits early.
  const tracks = enemy.attack === 'shot' || enemy.attack === 'spread' || enemy.attack === 'volley';
  if (tracks && enemy.stateTime > 0.15) {
    const angle = angleBetween(enemy.x, enemy.y, arena.player.x, arena.player.y);
    enemy.dirX = Math.cos(angle);
    enemy.dirY = Math.sin(angle);
  }
  if (enemy.stateTime > 0) return;
  enemy.state = 'attack';
  enemy.stateTime = ACTIVE[enemy.attack];
  arena.emit({ type: 'enemyAttack', id: enemy.id, attack: enemy.attack, x: enemy.x, y: enemy.y });
  launch(arena, enemy);
}

/** The instant part of an attack, fired as the attack phase begins. */
function launch(arena: Arena, enemy: Enemy): void {
  const p = arena.player;
  const def = enemy.def;
  const phase = PHASES[enemy.phase];
  const angle = Math.atan2(enemy.dirY, enemy.dirX);
  switch (enemy.attack) {
    case 'strike':
      if (inArc(enemy.x, enemy.y, angle, def.attackRange + 14, 0.95, p.x, p.y, p.radius)) {
        arena.damagePlayer(def.damage, enemy.x, enemy.y, 260);
        enemy.attackLanded = true;
      }
      enemy.knockX += enemy.dirX * 160;
      enemy.knockY += enemy.dirY * 160;
      break;
    case 'slam': {
      const radius = slamRadius(enemy);
      if (circlesTouch(enemy.x, enemy.y, radius, p.x, p.y, p.radius)) arena.damagePlayer(def.damage, enemy.x, enemy.y, 380);
      arena.emit({ type: 'shake', strength: enemy.isBoss ? 9 : 5 });
      break;
    }
    case 'shot':
      shoot(arena, enemy, angle, 230, def.damage);
      break;
    case 'spread':
      for (const offset of [-0.32, 0, 0.32]) shoot(arena, enemy, angle + offset, enemy.isBoss ? phase.speed + 20 : 210, def.damage);
      break;
    case 'ring': {
      const count = enemy.isBoss ? phase.ring : 8;
      const twist = arena.rng.range(0, Math.PI * 2);
      for (let i = 0; i < count; i++) shoot(arena, enemy, twist + (i / count) * Math.PI * 2, phase.speed, def.damage);
      break;
    }
    case 'summon':
      summon(arena, enemy);
      break;
    case 'lunge':
    case 'charge':
    case 'volley':
      // Continuous attacks resolve over the attack phase.
      break;
  }
}

export function slamRadius(enemy: Enemy): number {
  return enemy.def.attackRange + (enemy.isBoss ? 60 : 34);
}

function shoot(arena: Arena, enemy: Enemy, angle: number, speed: number, damage: number): void {
  arena.spawnProjectile({
    owner: 'enemy',
    x: enemy.x + Math.cos(angle) * enemy.radius,
    y: enemy.y + Math.sin(angle) * enemy.radius,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    radius: enemy.isBoss ? 8 : 7,
    damage,
    life: 3.5,
    pierce: 0,
  });
}

function summon(arena: Arena, boss: Enemy): void {
  const roster = ['memory_echo', 'scavenger'];
  for (let i = 0; i < 2; i++) {
    const angle = arena.rng.range(0, Math.PI * 2);
    const x = boss.x + Math.cos(angle) * 70;
    const y = boss.y + Math.sin(angle) * 70;
    if (arena.grid.isSolidAtPixel(x, y)) continue;
    arena.spawnEnemy(arena.rng.pick(roster), x, y, boss.roomId);
  }
}

function attack(arena: Arena, enemy: Enemy, dt: number): void {
  const p = arena.player;
  const def = enemy.def;
  if (enemy.attack === 'lunge' || enemy.attack === 'charge') {
    const speed = enemy.attack === 'charge' ? 520 : def.speed * 4 + 120;
    const hitWall = moveAndCollide(arena.grid, enemy, enemy.dirX * speed * dt, enemy.dirY * speed * dt);
    if (!enemy.attackLanded && circlesTouch(enemy.x, enemy.y, enemy.radius + 4, p.x, p.y, p.radius)) {
      arena.damagePlayer(def.damage, enemy.x, enemy.y, enemy.attack === 'charge' ? 420 : 260);
      enemy.attackLanded = true;
    }
    if (hitWall && enemy.attack === 'charge') {
      // Slamming into a wall leaves a boss open for a moment.
      arena.emit({ type: 'shake', strength: 7 });
      enemy.stateTime = 0;
      finishAttack(arena, enemy, 1.1);
      return;
    }
  } else if (enemy.attack === 'volley') {
    // Five aimed shots across the attack phase.
    const before = Math.floor(((ACTIVE.volley - enemy.stateTime - dt) / ACTIVE.volley) * 5);
    const after = Math.floor(((ACTIVE.volley - enemy.stateTime) / ACTIVE.volley) * 5);
    if (after > before && after <= 5) {
      const angle = angleBetween(enemy.x, enemy.y, p.x, p.y);
      shoot(arena, enemy, angle, PHASES[enemy.phase].speed + 40, def.damage);
    }
  }
  if (enemy.stateTime <= 0) finishAttack(arena, enemy, enemy.isBoss ? 0.55 : 0.45);
}

function finishAttack(arena: Arena, enemy: Enemy, recover: number): void {
  enemy.state = 'recover';
  enemy.stateTime = recover;
  const base = enemy.isBoss ? Math.max(1.1, enemy.def.attackCooldown) * PHASES[enemy.phase].cooldown : enemy.def.attackCooldown;
  enemy.cooldown = base * arena.rng.range(0.85, 1.2);
}

/** Advances a boss to the phase its health calls for. Returns true when it changed. */
export function updateBossPhase(enemy: Enemy): boolean {
  if (!enemy.isBoss) return false;
  const fraction = enemy.health / enemy.maxHealth;
  const phase = fraction <= 0.3 ? 2 : fraction <= 0.6 ? 1 : 0;
  if (phase <= enemy.phase) return false;
  enemy.phase = phase;
  return true;
}

/**
 * Run state: everything that carries from one floor to the next. It is plain
 * data, so saving a run is JSON.stringify and loading is JSON.parse plus
 * `restoreRun` (which recomputes derived stats).
 */
import type { Player } from './entities';
import { createPlayer, refreshStats } from './player';

export type ChoiceSource = 'level' | 'chest' | 'shrine';

export interface UpgradeChoice {
  source: ChoiceSource;
  options: string[];
}

export interface RunStats {
  kills: number;
  /** Seconds of simulated play. */
  elapsed: number;
  damageDealt: number;
  roomsCleared: number;
}

export interface RunState {
  /** Bumped when the shape changes, so old saves are rejected rather than misread. */
  version: 1;
  seed: number;
  depth: number;
  player: Player;
  stats: RunStats;
  /** Fragments found during this run. */
  fragmentsFound: string[];
  /** Fragments already owned (from earlier runs) when this run began. */
  knownFragments: string[];
  pendingChoices: UpgradeChoice[];
}

export function createRun(seed: number, knownFragments: readonly string[]): RunState {
  return {
    version: 1,
    seed: seed >>> 0,
    depth: 0,
    player: createPlayer(0, 0),
    stats: { kills: 0, elapsed: 0, damageDealt: 0, roomsCleared: 0 },
    fragmentsFound: [],
    knownFragments: [...knownFragments],
    pendingChoices: [],
  };
}

/** XP needed to go from `level` to `level + 1`. */
export function xpForLevel(level: number): number {
  return Math.round(30 * Math.pow(1.3, level - 1));
}

/** Adds XP, queues one level-up choice per level gained, and returns levels gained. */
export function grantXp(run: RunState, amount: number, rollOptions: () => string[]): number {
  const p = run.player;
  p.xp += amount;
  let gained = 0;
  while (p.xp >= xpForLevel(p.level)) {
    p.xp -= xpForLevel(p.level);
    p.level++;
    gained++;
    run.pendingChoices.push({ source: 'level', options: rollOptions() });
  }
  return gained;
}

/** Applies the first pending choice. Throws on an option that wasn't offered. */
export function applyChoice(run: RunState, upgradeId: string): void {
  const choice = run.pendingChoices[0];
  if (!choice) throw new Error('No upgrade choice is pending');
  if (!choice.options.includes(upgradeId)) throw new Error(`'${upgradeId}' was not offered`);
  run.pendingChoices.shift();
  const p = run.player;
  p.upgrades[upgradeId] = (p.upgrades[upgradeId] ?? 0) + 1;
  refreshStats(p);
  if (upgradeId === 'flask') p.potions = Math.min(p.stats.maxPotions, p.potions + 1);
}

/** Rebuilds derived fields after JSON.parse; returns undefined for unusable data. */
export function restoreRun(data: unknown): RunState | undefined {
  if (!data || typeof data !== 'object') return undefined;
  const run = data as RunState;
  if (run.version !== 1 || typeof run.seed !== 'number' || !run.player || typeof run.depth !== 'number') return undefined;
  if (!run.player.upgrades || typeof run.player.health !== 'number') return undefined;
  const health = run.player.health;
  const mana = run.player.mana;
  const dash = run.player.dashCharges;
  refreshStats(run.player);
  run.player.health = Math.min(health, run.player.stats.maxHealth);
  run.player.mana = Math.min(mana, run.player.stats.maxMana);
  run.player.dashCharges = Math.min(dash, run.player.stats.dashCharges);
  run.pendingChoices = Array.isArray(run.pendingChoices) ? run.pendingChoices : [];
  return run;
}

/**
 * One dungeon floor in play. `step` advances the simulation by a fixed time
 * step and returns the events that happened; nothing here touches the DOM or
 * the renderer, so tests and bots can drive a World headlessly.
 */
import { circlesTouch, type Arena, type DamageSource } from './combat';
import { enemyDef, fragmentsForFloor, floorPlan, FINAL_DEPTH, type FloorPlan } from './content';
import { generateFloor, roomAt, roomCentrePx, type FloorMap, type Room } from './dungeon';
import { createEnemy, killEnemy, staggerEnemy, updateBossPhase, updateEnemy } from './enemies';
import type { Enemy, InputFrame, Interactable, Pickup, Projectile } from './entities';
import type { SimEvent } from './events';
import { moveAndCollide, separate } from './physics';
import { updatePlayer } from './player';
import { Rng, floorSeed } from './rng';
import { applyChoice, grantXp, type RunState } from './run';
import { TILE_SIZE } from './tiles';
import { rollChoices } from './upgrades';

export type RoomPhase = 'dormant' | 'active' | 'cleared';

export interface RoomState {
  phase: RoomPhase;
  wavesLeft: number;
  /** Seconds until the next wave (or the boss) appears while active. */
  spawnDelay: number;
}

const INTERACT_RADIUS = 44;
const PORTAL_RADIUS = 26;
const HURT_IFRAMES = 0.75;

export class World implements Arena {
  readonly floor: FloorMap;
  readonly plan: FloorPlan;
  readonly rng: Rng;
  readonly enemies: Enemy[] = [];
  readonly projectiles: Projectile[] = [];
  readonly pickups: Pickup[] = [];
  readonly interactables: Interactable[] = [];
  readonly rooms: RoomState[];
  readonly visited: boolean[];
  /** Seconds of play on this floor. */
  time = 0;
  exited = false;
  victory = false;
  private nextId = 1;
  private freeze = 0;
  private events: SimEvent[] = [];
  private fragmentQueue: string[];
  private victoryDelay = -1;

  constructor(readonly run: RunState) {
    this.plan = floorPlan(run.depth);
    const seed = floorSeed(run.seed, run.depth);
    this.floor = generateFloor(seed, run.depth, { roomCount: this.plan.roomCount, finale: this.plan.finale });
    this.rng = new Rng(seed ^ 0x5bd1e995);
    this.rooms = this.floor.rooms.map((r) => ({
      phase: r.kind === 'combat' || r.kind === 'boss' ? 'dormant' : 'cleared',
      wavesLeft: 0,
      spawnDelay: 0,
    }));
    this.visited = this.floor.rooms.map(() => false);
    const owned = new Set([...run.knownFragments, ...run.fragmentsFound]);
    this.fragmentQueue = fragmentsForFloor(this.plan.biome, owned);

    const start = roomCentrePx(this.floor.rooms[this.floor.startRoom]);
    run.player.x = start.x;
    run.player.y = start.y + TILE_SIZE * 2;
    run.player.action = 'idle';
    run.player.knockX = 0;
    run.player.knockY = 0;
    this.placeInteractables();
  }

  get grid(): FloorMap['grid'] {
    return this.floor.grid;
  }

  get player(): RunState['player'] {
    return this.run.player;
  }

  get dead(): boolean {
    return this.run.player.action === 'dead';
  }

  /** True while the sim waits for the player to pick an upgrade. */
  get awaitingChoice(): boolean {
    return this.run.pendingChoices.length > 0;
  }

  /** The room the player is standing in, if any. */
  currentRoom(): Room | undefined {
    return roomAt(this.floor, this.player.x, this.player.y);
  }

  /** The interactable in reach, for the UI's prompt. */
  nearbyInteractable(): Interactable | undefined {
    const p = this.player;
    return this.interactables.find(
      (i) => !i.used && i.kind !== 'portal' && Math.hypot(i.x - p.x, i.y - p.y) <= INTERACT_RADIUS
    );
  }

  /** Living boss of the current floor, for the boss health bar. */
  activeBoss(): Enemy | undefined {
    return this.enemies.find((e) => e.isBoss && e.state !== 'dying');
  }

  chooseUpgrade(upgradeId: string): void {
    applyChoice(this.run, upgradeId);
  }

  step(input: InputFrame, dt: number): SimEvent[] {
    this.events = [];
    if (this.exited || this.awaitingChoice) return this.events;
    if (this.freeze > 0) {
      this.freeze -= dt;
      return this.events;
    }
    this.time += dt;
    this.run.stats.elapsed += dt;

    updatePlayer(this, input, dt);
    if (input.interact) this.interact();
    this.updateRooms(dt);
    this.updateEnemies(dt);
    this.updateProjectiles(dt);
    this.separateBodies();
    this.updatePickups(dt);
    this.checkPortal();
    if (this.victoryDelay > 0) {
      this.victoryDelay -= dt;
      if (this.victoryDelay <= 0) {
        this.victory = true;
        this.emit({ type: 'victory' });
      }
    }
    return this.events;
  }

  // ----- Arena -----

  emit(event: SimEvent): void {
    this.events.push(event);
  }

  hitstop(seconds: number): void {
    this.freeze = Math.max(this.freeze, seconds);
  }

  damageEnemy(enemy: Enemy, amount: number, source: DamageSource, crit: boolean, knockback: number): number {
    if (enemy.state === 'spawning' || enemy.state === 'dying') return 0;
    const dealt = Math.min(enemy.health, amount);
    enemy.health -= dealt;
    enemy.flash = 0.1;
    const p = this.player;
    const away = Math.atan2(enemy.y - p.y, enemy.x - p.x);
    const resist = enemy.isBoss ? 0.15 : enemy.def.archetype === 'brute' ? 0.4 : 1;
    enemy.knockX += Math.cos(away) * knockback * resist;
    enemy.knockY += Math.sin(away) * knockback * resist;
    this.run.stats.damageDealt += dealt;
    this.emit({ type: 'hit', x: enemy.x, y: enemy.y - enemy.radius, amount: dealt, crit, target: 'enemy' });
    if (source === 'melee' && p.stats.lifesteal > 0) {
      p.health = Math.min(p.stats.maxHealth, p.health + dealt * p.stats.lifesteal);
    }
    if (enemy.health <= 0) this.onEnemyKilled(enemy);
    else {
      staggerEnemy(enemy);
      if (updateBossPhase(enemy)) {
        this.emit({ type: 'bossPhase', phase: enemy.phase });
        this.emit({ type: 'shake', strength: 8 });
      }
    }
    return dealt;
  }

  damagePlayer(amount: number, fromX: number, fromY: number, knockback: number): void {
    const p = this.player;
    if (p.invulnerable > 0 || p.action === 'dead') return;
    const taken = Math.max(1, Math.round(amount * (1 - p.stats.damageReduction)));
    p.health = Math.max(0, p.health - taken);
    p.invulnerable = HURT_IFRAMES;
    p.hurtFlash = 0.25;
    const away = Math.atan2(p.y - fromY, p.x - fromX);
    p.knockX += Math.cos(away) * knockback;
    p.knockY += Math.sin(away) * knockback;
    this.emit({ type: 'hit', x: p.x, y: p.y - p.radius, amount: taken, crit: false, target: 'player' });
    this.emit({ type: 'playerHurt', amount: taken });
    this.emit({ type: 'shake', strength: 6 });
    this.hitstop(0.06);
    if (p.health <= 0) {
      p.action = 'dead';
      p.swingTime = -1;
      p.dashTime = 0;
      this.emit({ type: 'playerDied' });
    }
  }

  spawnProjectile(projectile: Omit<Projectile, 'id' | 'hitIds'>): void {
    this.projectiles.push({ ...projectile, id: this.nextId++, hitIds: [] });
  }

  spawnEnemy(defId: string, x: number, y: number, roomId: number, asBoss = false): Enemy {
    const depth = this.run.depth;
    const scale = { health: 1 + 0.12 * depth, damage: 1 + 0.08 * depth };
    const elite = !asBoss && depth > 0 && this.rng.chance(0.06 + 0.03 * depth);
    const enemy = createEnemy(this.nextId++, enemyDef(defId, asBoss), x, y, roomId, scale, elite);
    this.enemies.push(enemy);
    this.emit({ type: 'enemySpawned', id: enemy.id, x, y });
    return enemy;
  }

  // ----- floor flow -----

  private placeInteractables(): void {
    for (const room of this.floor.rooms) {
      const c = roomCentrePx(room);
      if (room.kind === 'treasure') this.addInteractable('chest', c.x, c.y, 0);
      if (room.kind === 'shrine') this.addInteractable('shrine', c.x, c.y, 25 + 15 * this.run.depth);
    }
  }

  private addInteractable(kind: Interactable['kind'], x: number, y: number, cost: number): void {
    this.interactables.push({ id: this.nextId++, kind, x, y, used: false, cost });
  }

  private interact(): void {
    const target = this.nearbyInteractable();
    if (!target) return;
    const p = this.player;
    if (target.kind === 'chest') {
      target.used = true;
      this.run.pendingChoices.push({ source: 'chest', options: rollChoices(this.rng, p.upgrades, 3, 'generous') });
      this.dropFragment(target.x + 40, target.y);
      this.dropShards(target.x, target.y, 8 + 4 * this.run.depth);
      this.emit({ type: 'interact', kind: 'chest', x: target.x, y: target.y });
    } else if (target.kind === 'shrine') {
      if (p.shards < target.cost) {
        this.emit({ type: 'notice', text: `The well asks for ${target.cost} shards` });
        return;
      }
      p.shards -= target.cost;
      target.used = true;
      p.health = Math.min(p.stats.maxHealth, p.health + p.stats.maxHealth * 0.5);
      p.potions = p.stats.maxPotions;
      this.run.pendingChoices.push({ source: 'shrine', options: rollChoices(this.rng, p.upgrades, 3, 'generous') });
      this.emit({ type: 'interact', kind: 'shrine', x: target.x, y: target.y });
    }
  }

  private updateRooms(dt: number): void {
    const room = this.currentRoom();
    if (room) this.visited[room.id] = true;
    if (room && this.rooms[room.id].phase === 'dormant' && this.isDeepInside(room)) this.activateRoom(room);

    this.floor.rooms.forEach((r, id) => {
      const state = this.rooms[id];
      if (state.phase !== 'active') return;
      if (state.spawnDelay > 0) {
        state.spawnDelay -= dt;
        if (state.spawnDelay <= 0) this.spawnWave(r);
        return;
      }
      const alive = this.enemies.some((e) => e.roomId === id && e.state !== 'dying');
      if (alive) return;
      if (state.wavesLeft > 0) state.spawnDelay = 0.6;
      else this.clearRoom(r);
    });
  }

  /** The player is clear of the doorway ring, so closing the doors can't trap them in a wall. */
  private isDeepInside(room: Room): boolean {
    const p = this.player;
    const margin = TILE_SIZE + p.radius;
    return (
      p.x > room.x * TILE_SIZE + margin &&
      p.y > room.y * TILE_SIZE + margin &&
      p.x < (room.x + room.w) * TILE_SIZE - margin &&
      p.y < (room.y + room.h) * TILE_SIZE - margin
    );
  }

  private activateRoom(room: Room): void {
    const state = this.rooms[room.id];
    state.phase = 'active';
    this.setRoomLocked(room, true);
    this.emit({ type: 'roomLocked', roomId: room.id });
    if (room.kind === 'boss') {
      state.wavesLeft = 1;
      state.spawnDelay = 1.0;
      this.emit({ type: 'bossIntro', name: enemyDef(this.plan.boss).name });
    } else {
      const area = room.w * room.h;
      state.wavesLeft = this.run.depth >= 1 && area >= 150 ? 2 : 1;
      if (this.run.depth >= 3 && area >= 220) state.wavesLeft = 3;
      state.spawnDelay = 0.35;
    }
  }

  private spawnWave(room: Room): void {
    const state = this.rooms[room.id];
    state.wavesLeft--;
    if (room.kind === 'boss') {
      const c = roomCentrePx(room);
      this.spawnEnemy(this.plan.boss, c.x, c.y - TILE_SIZE * 2, room.id, true);
      return;
    }
    const count = 2 + Math.floor(this.run.depth * 0.6) + this.rng.int(0, 2);
    for (let i = 0; i < count; i++) {
      const spot = this.spawnPoint(room);
      if (spot) this.spawnEnemy(this.rng.pick(this.plan.roster), spot.x, spot.y, room.id);
    }
  }

  /** A random open spot in the room, kept away from the player. */
  private spawnPoint(room: Room): { x: number; y: number } | undefined {
    const p = this.player;
    for (let attempt = 0; attempt < 40; attempt++) {
      const tx = this.rng.int(room.x + 1, room.x + room.w - 2);
      const ty = this.rng.int(room.y + 1, room.y + room.h - 2);
      const x = (tx + 0.5) * TILE_SIZE;
      const y = (ty + 0.5) * TILE_SIZE;
      if (this.grid.isSolid(tx, ty) || Math.hypot(x - p.x, y - p.y) < 140) continue;
      return { x, y };
    }
    return undefined;
  }

  private clearRoom(room: Room): void {
    this.rooms[room.id].phase = 'cleared';
    this.setRoomLocked(room, false);
    this.run.stats.roomsCleared++;
    this.emit({ type: 'roomCleared', roomId: room.id });
    const c = roomCentrePx(room);
    if (room.kind === 'boss') {
      this.dropFragment(c.x + 40, c.y);
      if (this.run.depth >= FINAL_DEPTH) this.victoryDelay = 2.5;
      else this.addInteractable('portal', c.x, c.y, 0);
      return;
    }
    if (this.rng.chance(0.35)) this.dropPickup('health', c.x, c.y, 15);
  }

  private setRoomLocked(room: Room, locked: boolean): void {
    for (const door of room.doors) for (const t of door.tiles) this.grid.setDoorLocked(t.x, t.y, locked);
  }

  private onEnemyKilled(enemy: Enemy): void {
    killEnemy(enemy);
    const run = this.run;
    run.stats.kills++;
    this.emit({ type: 'enemyDied', id: enemy.id, x: enemy.x, y: enemy.y, boss: enemy.isBoss });
    this.emit({ type: 'shake', strength: enemy.isBoss ? 14 : 3 });
    if (enemy.isBoss) {
      this.hitstop(0.25);
      // The boss's summons crumble with it.
      for (const e of this.enemies) if (e !== enemy && e.roomId === enemy.roomId && e.state !== 'dying') killEnemy(e);
    }
    const p = this.player;
    p.mana = Math.min(p.stats.maxMana, p.mana + p.stats.manaOnKill);
    const xp = Math.round(enemy.def.xp * (1 + 0.1 * run.depth) * (enemy.elite ? 2 : 1));
    const levels = grantXp(run, xp, () => rollChoices(this.rng, p.upgrades));
    if (levels > 0) this.emit({ type: 'levelUp', level: p.level });
    this.dropShards(enemy.x, enemy.y, enemy.isBoss ? 30 : this.rng.int(1, 3) + (enemy.elite ? 5 : 0));
    if (!enemy.isBoss && this.rng.chance(0.07)) this.dropPickup('health', enemy.x, enemy.y, 12);
    if (!enemy.isBoss && this.rng.chance(0.025)) this.dropPickup('potion', enemy.x, enemy.y, 1);
  }

  private dropShards(x: number, y: number, total: number): void {
    // Several small shards scatter and then home in, which reads better than one big drop.
    const pieces = Math.min(total, 8);
    for (let i = 0; i < pieces; i++) {
      const share = Math.floor(total / pieces) + (i < total % pieces ? 1 : 0);
      this.dropPickup('shard', x, y, share);
    }
  }

  private dropPickup(kind: Pickup['kind'], x: number, y: number, amount: number, fragmentId?: string): void {
    const angle = this.rng.range(0, Math.PI * 2);
    const speed = kind === 'fragment' ? 0 : this.rng.range(60, 170);
    this.pickups.push({
      id: this.nextId++,
      kind,
      x,
      y,
      amount,
      fragmentId,
      age: 0,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
    });
  }

  private dropFragment(x: number, y: number): void {
    const id = this.fragmentQueue.shift();
    if (id) this.dropPickup('fragment', x, y, 1, id);
  }

  private updateEnemies(dt: number): void {
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      if (!updateEnemy(this, this.enemies[i], dt)) this.enemies.splice(i, 1);
    }
  }

  private updateProjectiles(dt: number): void {
    const p = this.player;
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const b = this.projectiles[i];
      b.life -= dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      let dead = b.life <= 0 || this.grid.isSolidAtPixel(b.x, b.y);
      if (!dead && b.owner === 'enemy') {
        if (p.action !== 'dead' && circlesTouch(b.x, b.y, b.radius, p.x, p.y, p.radius - 2)) {
          if (p.invulnerable <= 0) {
            this.damagePlayer(b.damage, b.x - b.vx, b.y - b.vy, 180);
            dead = true;
          }
        }
      } else if (!dead) {
        for (const e of this.enemies) {
          if (e.state === 'spawning' || e.state === 'dying' || b.hitIds.includes(e.id)) continue;
          if (!circlesTouch(b.x, b.y, b.radius, e.x, e.y, e.radius)) continue;
          b.hitIds.push(e.id);
          const crit = this.rng.chance(p.stats.critChance);
          const amount = Math.round(b.damage * (crit ? p.stats.critMultiplier : 1));
          this.damageEnemy(e, amount, 'bolt', crit, 90);
          if (b.pierce-- <= 0) {
            dead = true;
            break;
          }
        }
      }
      if (dead) this.projectiles.splice(i, 1);
    }
  }

  private separateBodies(): void {
    const p = this.player;
    const living = this.enemies.filter((e) => e.state !== 'dying' && e.state !== 'spawning');
    for (let i = 0; i < living.length; i++) {
      for (let j = i + 1; j < living.length; j++) separate(this.grid, living[i], living[j]);
      // The player phases through enemies while dashing.
      if (p.dashTime <= 0 && p.action !== 'dead') separate(this.grid, p, living[i], living[i].isBoss ? 0.9 : 0.35);
    }
  }

  private updatePickups(dt: number): void {
    const p = this.player;
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const item = this.pickups[i];
      item.age += dt;
      const dist = Math.hypot(p.x - item.x, p.y - item.y);
      const homing = item.age > 0.35 && p.action !== 'dead' && (item.kind === 'shard' ? dist < p.stats.pickupRadius * 2.2 : dist < p.stats.pickupRadius);
      if (homing && item.kind !== 'fragment') {
        const pull = 520;
        item.vx = ((p.x - item.x) / (dist || 1)) * pull;
        item.vy = ((p.y - item.y) / (dist || 1)) * pull;
      } else {
        const decay = Math.exp(-5 * dt);
        item.vx *= decay;
        item.vy *= decay;
      }
      const body = { x: item.x, y: item.y, radius: 4 };
      moveAndCollide(this.grid, body, item.vx * dt, item.vy * dt);
      item.x = body.x;
      item.y = body.y;
      if (item.age > 0.2 && dist < p.radius + 10 && p.action !== 'dead' && this.collect(item)) this.pickups.splice(i, 1);
    }
  }

  /** Applies a pickup; returns false to leave it on the floor (e.g. full health). */
  private collect(item: Pickup): boolean {
    const p = this.player;
    switch (item.kind) {
      case 'shard':
        p.shards += item.amount;
        break;
      case 'health':
        if (p.health >= p.stats.maxHealth) return false;
        p.health = Math.min(p.stats.maxHealth, p.health + item.amount);
        break;
      case 'potion':
        if (p.potions >= p.stats.maxPotions) return false;
        p.potions++;
        break;
      case 'fragment':
        if (item.fragmentId) {
          this.run.fragmentsFound.push(item.fragmentId);
          this.emit({ type: 'fragmentFound', fragmentId: item.fragmentId });
        }
        break;
    }
    this.emit({ type: 'pickup', kind: item.kind, x: item.x, y: item.y, amount: item.amount });
    return true;
  }

  private checkPortal(): void {
    const p = this.player;
    const portal = this.interactables.find((i) => i.kind === 'portal');
    if (!portal || p.action === 'dead') return;
    if (Math.hypot(portal.x - p.x, portal.y - p.y) < PORTAL_RADIUS) {
      this.exited = true;
      this.emit({ type: 'floorExit' });
    }
  }
}

