/**
 * Render palettes per biome. biomes.json carries thematic colours; these are
 * tuned for top-down readability (floor clearly lighter than walls, walls
 * clearly lighter than the void) while keeping each biome's identity.
 */
import type { BiomeId } from '../sim/content';

export type FloorStyle = 'slabs' | 'grass' | 'rock' | 'facets' | 'tiles';

export interface BiomeArt {
  floor: string;
  floorAlt: string;
  grout: string;
  wallCap: string;
  wallFace: string;
  wallMortar: string;
  wallHighlight: string;
  /** Glyphs, door barriers and ambient motes. */
  accent: string;
  /** Moss / flowers / crystals scattered on floors. */
  growth: string;
  background: number;
  /** Darkness around the player's light; alpha at the screen edge. */
  darkness: number;
  floorStyle: FloorStyle;
}

export const BIOME_ART: Record<BiomeId, BiomeArt> = {
  ruins: {
    floor: '#6e5c49',
    floorAlt: '#625241',
    grout: '#463a2f',
    wallCap: '#2b2521',
    wallFace: '#8c7459',
    wallMortar: '#5b4b3c',
    wallHighlight: '#b8a083',
    accent: '#ffd98a',
    growth: '#6f8a45',
    background: 0x0f0c0a,
    darkness: 0.62,
    floorStyle: 'slabs',
  },
  forest: {
    floor: '#3f5c2f',
    floorAlt: '#37522a',
    grout: '#2b3f1f',
    wallCap: '#17230f',
    wallFace: '#5d5a3e',
    wallMortar: '#3e3c28',
    wallHighlight: '#8fae68',
    accent: '#b7ff8a',
    growth: '#e8d36a',
    background: 0x081006,
    darkness: 0.66,
    floorStyle: 'grass',
  },
  caves: {
    floor: '#45465a',
    floorAlt: '#3d3e50',
    grout: '#2b2c3a',
    wallCap: '#15151d',
    wallFace: '#55566e',
    wallMortar: '#383949',
    wallHighlight: '#8a8ba6',
    accent: '#ff9a5a',
    growth: '#6fe7ff',
    background: 0x07070b,
    darkness: 0.72,
    floorStyle: 'rock',
  },
  crystal: {
    floor: '#3f3158',
    floorAlt: '#382b4f',
    grout: '#271d39',
    wallCap: '#170f25',
    wallFace: '#5f4486',
    wallMortar: '#3d2b58',
    wallHighlight: '#c7a2ff',
    accent: '#ff8ad8',
    growth: '#9ef3ff',
    background: 0x0c0716,
    darkness: 0.64,
    floorStyle: 'facets',
  },
  void: {
    floor: '#232740',
    floorAlt: '#1f2238',
    grout: '#141628',
    wallCap: '#08090f',
    wallFace: '#323858',
    wallMortar: '#1f2339',
    wallHighlight: '#6672a8',
    accent: '#6fe7ff',
    growth: '#b89cff',
    background: 0x030307,
    darkness: 0.74,
    floorStyle: 'tiles',
  },
  sanctuary: {
    floor: '#8c7d5c',
    floorAlt: '#837454',
    grout: '#5f5538',
    wallCap: '#3a3221',
    wallFace: '#c4ad78',
    wallMortar: '#8a7850',
    wallHighlight: '#fff0c2',
    accent: '#fff4d0',
    growth: '#ffd98a',
    background: 0x171307,
    darkness: 0.5,
    floorStyle: 'tiles',
  },
};

/** '#rrggbb' -> 0xrrggbb */
export function hex(color: string): number {
  return parseInt(color.slice(1), 16);
}

/**
 * Procedural top-down tile art, painted with Canvas2D once per floor.
 *
 * Walls read in 3/4 view: a dark cap seen from above, and a lit brick face on
 * every wall whose south neighbour is walkable. Floors next to walls get
 * ambient-occlusion overlays so rooms read as enclosed spaces.
 */
import { Texture } from 'pixi.js';
import type { BiomeId } from '../sim/content';
import { Rng } from '../sim/rng';
import { Deco, TILE_SIZE } from '../sim/tiles';
import { BIOME_ART, type BiomeArt } from './palette';

const T = TILE_SIZE;

export interface TileTextures {
  floor: Texture[];
  wallCap: Texture;
  /** Cap with a lit lip on its south edge, used directly above a wall face. */
  wallCapLip: Texture;
  wallFace: Texture[];
  aoNorth: Texture;
  aoWest: Texture;
  aoEast: Texture;
  threshold: Texture;
  deco: Partial<Record<Deco, Texture>>;
}

function canvas(w = T, h = T): { el: HTMLCanvasElement; ctx: CanvasRenderingContext2D } {
  const el = document.createElement('canvas');
  el.width = w;
  el.height = h;
  const ctx = el.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is unavailable; the game needs a browser with canvas support');
  return { el, ctx };
}

function toTexture(el: HTMLCanvasElement): Texture {
  const texture = Texture.from(el);
  texture.source.scaleMode = 'nearest';
  return texture;
}

/** Lightens (amount > 0) or darkens (amount < 0) a '#rrggbb' colour. */
export function shade(color: string, amount: number): string {
  const n = parseInt(color.slice(1), 16);
  const mix = (c: number): number =>
    Math.round(amount >= 0 ? c + (255 - c) * amount : c * (1 + amount));
  const r = mix((n >> 16) & 255);
  const g = mix((n >> 8) & 255);
  const b = mix(n & 255);
  return `rgb(${r},${g},${b})`;
}

function speckle(ctx: CanvasRenderingContext2D, rng: Rng, base: string, count: number, spread = 0.12): void {
  for (let i = 0; i < count; i++) {
    ctx.fillStyle = shade(base, rng.range(-spread, spread));
    ctx.fillRect(rng.int(0, T - 1), rng.int(0, T - 1), rng.chance(0.3) ? 2 : 1, 1);
  }
}

function paintFloor(art: BiomeArt, rng: Rng, variant: number): Texture {
  const { el, ctx } = canvas();
  const base = variant % 2 === 0 ? art.floor : art.floorAlt;
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, T, T);

  switch (art.floorStyle) {
    case 'slabs': {
      // Four worn flagstones with grout lines and chipped corners.
      for (const [sx, sy] of [
        [0, 0],
        [16, 0],
        [0, 16],
        [16, 16],
      ]) {
        ctx.fillStyle = shade(base, rng.range(-0.08, 0.06));
        ctx.fillRect(sx + 1, sy + 1, 15, 15);
        ctx.fillStyle = shade(base, 0.1);
        ctx.fillRect(sx + 1, sy + 1, 15, 1);
      }
      ctx.fillStyle = art.grout;
      ctx.fillRect(0, 0, T, 1);
      ctx.fillRect(0, 16, T, 1);
      ctx.fillRect(0, 0, 1, T);
      ctx.fillRect(16, 0, 1, T);
      speckle(ctx, rng, base, 40);
      break;
    }
    case 'grass': {
      speckle(ctx, rng, base, 70, 0.18);
      for (let i = 0; i < 12; i++) {
        const x = rng.int(1, T - 2);
        const y = rng.int(2, T - 1);
        ctx.fillStyle = shade(base, rng.range(0.1, 0.3));
        ctx.fillRect(x, y - 2, 1, 2);
      }
      if (variant === 3) {
        ctx.fillStyle = shade(art.grout, -0.1);
        ctx.fillRect(rng.int(4, 20), rng.int(4, 20), 7, 5);
      }
      break;
    }
    case 'rock': {
      for (let i = 0; i < 5; i++) {
        ctx.fillStyle = shade(base, rng.range(-0.12, 0.08));
        ctx.beginPath();
        ctx.ellipse(rng.int(0, T), rng.int(0, T), rng.int(5, 11), rng.int(4, 8), rng.range(0, 3), 0, Math.PI * 2);
        ctx.fill();
      }
      speckle(ctx, rng, base, 50, 0.16);
      break;
    }
    case 'facets': {
      // Diagonal crystal facets.
      ctx.fillStyle = shade(base, 0.06);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(T, 0);
      ctx.lineTo(0, T);
      ctx.fill();
      ctx.strokeStyle = art.grout;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(T, 0);
      ctx.lineTo(0, T);
      ctx.stroke();
      ctx.strokeRect(0.5, 0.5, T - 1, T - 1);
      speckle(ctx, rng, base, 25);
      break;
    }
    case 'tiles': {
      ctx.fillStyle = shade(base, 0.05);
      ctx.fillRect(2, 2, T - 4, T - 4);
      ctx.fillStyle = art.grout;
      ctx.fillRect(0, 0, T, 2);
      ctx.fillRect(0, 0, 2, T);
      ctx.fillStyle = shade(base, 0.16);
      ctx.fillRect(2, 2, T - 4, 1);
      if (variant === 0) {
        ctx.strokeStyle = shade(art.accent, -0.5);
        ctx.globalAlpha = 0.35;
        ctx.strokeRect(10.5, 10.5, 11, 11);
        ctx.globalAlpha = 1;
      }
      speckle(ctx, rng, base, 20, 0.08);
      break;
    }
  }
  return toTexture(el);
}

function paintWallCap(art: BiomeArt, rng: Rng, lip: boolean): Texture {
  const { el, ctx } = canvas();
  ctx.fillStyle = art.wallCap;
  ctx.fillRect(0, 0, T, T);
  speckle(ctx, rng, art.wallCap, 30, 0.15);
  if (lip) {
    ctx.fillStyle = shade(art.wallHighlight, -0.15);
    ctx.fillRect(0, T - 4, T, 2);
    ctx.fillStyle = art.wallHighlight;
    ctx.fillRect(0, T - 2, T, 2);
  }
  return toTexture(el);
}

function paintWallFace(art: BiomeArt, rng: Rng, variant: number): Texture {
  const { el, ctx } = canvas();
  ctx.fillStyle = art.wallFace;
  ctx.fillRect(0, 0, T, T);
  // Brick courses, 8px tall, alternating offset.
  for (let row = 0; row < 4; row++) {
    const y = row * 8;
    const offset = (row + variant) % 2 === 0 ? 0 : 8;
    for (let x = -offset; x < T; x += 16) {
      ctx.fillStyle = shade(art.wallFace, rng.range(-0.1, 0.08) - row * 0.05);
      ctx.fillRect(x + 1, y + 1, 14, 6);
      ctx.fillStyle = shade(art.wallFace, 0.12 - row * 0.04);
      ctx.fillRect(x + 1, y + 1, 14, 1);
    }
    ctx.fillStyle = art.wallMortar;
    ctx.fillRect(0, y, T, 1);
  }
  // Light from above, occlusion where the wall meets the floor.
  const gradient = ctx.createLinearGradient(0, 0, 0, T);
  gradient.addColorStop(0, 'rgba(255,255,255,0.10)');
  gradient.addColorStop(0.7, 'rgba(0,0,0,0)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.35)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, T, T);
  return toTexture(el);
}

function paintOcclusion(direction: 'north' | 'west' | 'east'): Texture {
  const { el, ctx } = canvas();
  const depth = direction === 'north' ? 14 : 8;
  const gradient =
    direction === 'north'
      ? ctx.createLinearGradient(0, 0, 0, depth)
      : direction === 'west'
        ? ctx.createLinearGradient(0, 0, depth, 0)
        : ctx.createLinearGradient(T, 0, T - depth, 0);
  gradient.addColorStop(0, `rgba(0,0,0,${direction === 'north' ? 0.55 : 0.35})`);
  gradient.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, T, T);
  return toTexture(el);
}

function paintThreshold(art: BiomeArt): Texture {
  const { el, ctx } = canvas();
  ctx.fillStyle = shade(art.grout, -0.2);
  ctx.globalAlpha = 0.5;
  for (let i = 0; i < T; i += 6) ctx.fillRect(i, 0, 3, T);
  return toTexture(el);
}

function paintDeco(art: BiomeArt, rng: Rng, kind: Deco): Texture {
  const { el, ctx } = canvas();
  switch (kind) {
    case Deco.Crack: {
      ctx.strokeStyle = shade(art.grout, -0.3);
      ctx.lineWidth = 1;
      ctx.beginPath();
      let x = rng.int(4, 12);
      let y = rng.int(4, 12);
      ctx.moveTo(x, y);
      for (let i = 0; i < 4; i++) {
        x += rng.int(2, 6);
        y += rng.int(-2, 5);
        ctx.lineTo(x, y);
      }
      ctx.stroke();
      break;
    }
    case Deco.Rubble:
      for (let i = 0; i < 4; i++) {
        const x = rng.int(4, 26);
        const y = rng.int(4, 26);
        const s = rng.int(2, 4);
        ctx.fillStyle = shade(art.wallFace, -0.2);
        ctx.fillRect(x, y, s, s);
        ctx.fillStyle = shade(art.wallHighlight, -0.1);
        ctx.fillRect(x, y, s, 1);
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fillRect(x, y + s, s, 1);
      }
      break;
    case Deco.Moss:
      for (let i = 0; i < 6; i++) {
        ctx.fillStyle = shade(art.growth, rng.range(-0.3, 0.1));
        ctx.globalAlpha = 0.8;
        ctx.beginPath();
        ctx.arc(rng.int(6, 26), rng.int(6, 26), rng.int(1, 3), 0, Math.PI * 2);
        ctx.fill();
      }
      break;
    case Deco.Glyph:
      ctx.strokeStyle = art.accent;
      ctx.globalAlpha = 0.7;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(16, 16, 9, 0, Math.PI * 2);
      ctx.moveTo(16, 8);
      ctx.lineTo(16, 24);
      ctx.moveTo(10, 13);
      ctx.lineTo(22, 19);
      ctx.stroke();
      break;
    case Deco.None:
      break;
  }
  return toTexture(el);
}

const cache = new Map<BiomeId, TileTextures>();

/** Tile textures for a biome, painted on first use. */
export function tileTextures(biome: BiomeId): TileTextures {
  const cached = cache.get(biome);
  if (cached) return cached;
  const art = BIOME_ART[biome];
  const rng = new Rng(biome.length * 7919 + biome.charCodeAt(0));
  const textures: TileTextures = {
    floor: [0, 1, 2, 3].map((v) => paintFloor(art, rng, v)),
    wallCap: paintWallCap(art, rng, false),
    wallCapLip: paintWallCap(art, rng, true),
    wallFace: [0, 1].map((v) => paintWallFace(art, rng, v)),
    aoNorth: paintOcclusion('north'),
    aoWest: paintOcclusion('west'),
    aoEast: paintOcclusion('east'),
    threshold: paintThreshold(art),
    deco: {
      [Deco.Crack]: paintDeco(art, rng, Deco.Crack),
      [Deco.Rubble]: paintDeco(art, rng, Deco.Rubble),
      [Deco.Moss]: paintDeco(art, rng, Deco.Moss),
      [Deco.Glyph]: paintDeco(art, rng, Deco.Glyph),
    },
  };
  cache.set(biome, textures);
  return textures;
}

/**
 * Small generated textures for lights and particles.
 */
import { Texture } from 'pixi.js';

export interface FxTextures {
  /** Soft white radial falloff; tint and add-blend it for lights. */
  glow: Texture;
  /** Tight bright dot for sparks and projectile cores. */
  spark: Texture;
  /** Thin ring for shockwaves and pickups. */
  ring: Texture;
  /** Screen-space darkness with a clear centre, stretched over the viewport. */
  vignette: Texture;
}

function paint(size: number, draw: (ctx: CanvasRenderingContext2D, size: number) => void): Texture {
  const el = document.createElement('canvas');
  el.width = size;
  el.height = size;
  const ctx = el.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is unavailable; the game needs a browser with canvas support');
  draw(ctx, size);
  return Texture.from(el);
}

let cached: FxTextures | undefined;

export function fxTextures(): FxTextures {
  if (cached) return cached;
  cached = {
    glow: paint(128, (ctx, s) => {
      const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
      g.addColorStop(0, 'rgba(255,255,255,1)');
      g.addColorStop(0.25, 'rgba(255,255,255,0.55)');
      g.addColorStop(0.6, 'rgba(255,255,255,0.12)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, s, s);
    }),
    spark: paint(16, (ctx, s) => {
      const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
      g.addColorStop(0, 'rgba(255,255,255,1)');
      g.addColorStop(0.5, 'rgba(255,255,255,0.8)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, s, s);
    }),
    ring: paint(128, (ctx, s) => {
      ctx.strokeStyle = 'rgba(255,255,255,1)';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.arc(s / 2, s / 2, s / 2 - 6, 0, Math.PI * 2);
      ctx.stroke();
    }),
    vignette: paint(512, (ctx, s) => {
      const g = ctx.createRadialGradient(s / 2, s / 2, s * 0.14, s / 2, s / 2, s * 0.72);
      g.addColorStop(0, 'rgba(0,0,0,0)');
      g.addColorStop(0.55, 'rgba(0,0,0,0.45)');
      g.addColorStop(1, 'rgba(0,0,0,1)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, s, s);
    }),
  };
  return cached;
}

/**
 * Sprite sheets described by sprite_atlas.json, cut into frame textures.
 */
import { Assets, Rectangle, Texture } from 'pixi.js';
import atlas from '@data/sprite_atlas.json';

export interface Animation {
  frames: Texture[];
  fps: number;
  loop: boolean;
}

export interface ActorSheet {
  idle: Animation;
  walk: Animation;
  attack: Animation;
  death: Animation;
  /** Present for the player only. */
  dash?: Animation;
  originX: number;
  originY: number;
  frameHeight: number;
}

export interface SpriteLibrary {
  player: ActorSheet;
  enemies: Record<string, ActorSheet>;
  props: Record<string, Texture>;
  ui: Record<string, Texture>;
}

interface AtlasEnemy {
  texture: string;
  frameWidth: number;
  frameHeight: number;
  origin: { x: number; y: number };
  animations: Record<string, { row: number; frames: number; fps: number; loop: boolean }>;
}

interface AtlasPlayerAnim {
  texture: string;
  frames: number;
  fps: number;
  loop: boolean;
}

interface Atlas {
  player: {
    frameSize: { width: number; height: number };
    origin: { x: number; y: number };
    animations: Record<string, AtlasPlayerAnim>;
  };
  enemies: Record<string, AtlasEnemy>;
  props: Record<string, string>;
  ui: Record<string, string>;
}

const data = atlas as Atlas;

function url(path: string): string {
  const base = import.meta.env.BASE_URL || '/';
  return `${base}${path.replace(/^\/+/, '')}`;
}

function cut(source: Texture, x: number, y: number, w: number, h: number): Texture {
  return new Texture({ source: source.source, frame: new Rectangle(x, y, w, h) });
}

function strip(source: Texture, row: number, count: number, w: number, h: number, columns = count): Texture[] {
  return Array.from({ length: Math.min(count, columns) }, (_, i) => cut(source, i * w, row * h, w, h));
}

async function loadTexture(path: string): Promise<Texture> {
  const texture = await Assets.load<Texture>(url(path));
  texture.source.scaleMode = 'linear';
  return texture;
}

async function loadPlayer(): Promise<ActorSheet> {
  const p = data.player;
  const w = p.frameSize.width;
  const h = p.frameSize.height;
  const anim = async (key: string): Promise<Animation> => {
    const a = p.animations[key];
    const texture = await loadTexture(a.texture);
    return { frames: strip(texture, 0, a.frames, w, h), fps: a.fps, loop: a.loop };
  };
  const [idle, walk, attack, dash] = await Promise.all([anim('idle'), anim('walk'), anim('attack'), anim('dash')]);
  // The player sheet has no death strip; the idle pose fades out instead.
  return { idle, walk, attack, dash, death: { ...idle, loop: false }, originX: p.origin.x, originY: p.origin.y, frameHeight: h };
}

async function loadEnemy(entry: AtlasEnemy): Promise<ActorSheet> {
  const texture = await loadTexture(entry.texture);
  const w = entry.frameWidth;
  const h = entry.frameHeight;
  const row = (key: string, frames?: number): Animation => {
    const a = entry.animations[key];
    return { frames: strip(texture, a.row, frames ?? a.frames, w, h), fps: a.fps, loop: a.loop };
  };
  const idle = row('idle');
  return {
    idle,
    // Most generated walk strips have empty odd frames, so walking reuses the
    // idle strip (faster) and the view adds a bob.
    walk: { frames: idle.frames, fps: idle.fps * 2, loop: true },
    attack: row('attack'),
    // The last death frame is blank; stop on the third.
    death: row('death', 3),
    originX: entry.origin.x,
    originY: entry.origin.y,
    frameHeight: h,
  };
}

export async function loadSprites(onProgress?: (fraction: number) => void): Promise<SpriteLibrary> {
  const enemyKeys = Object.keys(data.enemies);
  const total = enemyKeys.length + Object.keys(data.props).length + Object.keys(data.ui).length + 1;
  let done = 0;
  const tick = <T>(value: T): T => {
    done++;
    onProgress?.(done / total);
    return value;
  };

  const player = tick(await loadPlayer());
  const enemies: Record<string, ActorSheet> = {};
  await Promise.all(
    enemyKeys.map(async (key) => {
      enemies[key] = tick(await loadEnemy(data.enemies[key]));
    })
  );
  const loadMap = async (map: Record<string, string>): Promise<Record<string, Texture>> => {
    const out: Record<string, Texture> = {};
    await Promise.all(
      Object.entries(map).map(async ([key, path]) => {
        out[key] = tick(await loadTexture(path));
      })
    );
    return out;
  };
  const [props, ui] = await Promise.all([loadMap(data.props), loadMap(data.ui)]);
  return { player, enemies, props, ui };
}

/** Every image path the atlas references, for asset checks. */
export function atlasImagePaths(): string[] {
  return [
    ...Object.values(data.player.animations).map((a) => a.texture),
    ...Object.values(data.enemies).map((e) => e.texture),
    ...Object.values(data.props),
    ...Object.values(data.ui),
  ];
}

/**
 * Static floor rendering: tile sprites grouped into chunks (hidden when off
 * screen), animated door barriers and glyph lights.
 */
import { Container, Graphics, Sprite, type Texture } from 'pixi.js';
import type { BiomeId } from '../sim/content';
import type { FloorMap } from '../sim/dungeon';
import { Deco, Tile, TILE_SIZE, type TileGrid } from '../sim/tiles';
import { fxTextures } from './fxArt';
import { BIOME_ART, hex } from './palette';
import { tileTextures } from './tileArt';

const CHUNK = 16;
const T = TILE_SIZE;

interface Chunk {
  container: Container;
  x0: number;
  y0: number;
}

/** Stable per-tile variant so a floor looks the same every time it's built. */
function variantAt(tx: number, ty: number, count: number): number {
  const h = Math.imul(tx * 374761393 + ty * 668265263, 1274126177) >>> 0;
  return (h >>> 13) % count;
}

export class LevelView {
  readonly root = new Container();
  private readonly chunks: Chunk[] = [];
  private readonly doors = new Graphics();
  private readonly glyphs: Sprite[] = [];
  private readonly accent: number;
  private time = 0;

  constructor(
    private readonly floor: FloorMap,
    biome: BiomeId
  ) {
    this.accent = hex(BIOME_ART[biome].accent);
    this.build(biome);
    this.root.addChild(this.doors);
  }

  private build(biome: BiomeId): void {
    const grid = this.floor.grid;
    const tex = tileTextures(biome);
    const glowLayer = new Container();
    for (let cy = 0; cy < grid.height; cy += CHUNK) {
      for (let cx = 0; cx < grid.width; cx += CHUNK) {
        const container = new Container();
        let used = false;
        for (let ty = cy; ty < Math.min(cy + CHUNK, grid.height); ty++) {
          for (let tx = cx; tx < Math.min(cx + CHUNK, grid.width); tx++) {
            used = this.addTile(container, glowLayer, grid, tex, tx, ty) || used;
          }
        }
        if (!used) continue;
        this.root.addChild(container);
        this.chunks.push({ container, x0: cx * T, y0: cy * T });
      }
    }
    this.root.addChild(glowLayer);
  }

  /** Adds the sprites for one tile; returns whether anything was drawn. */
  private addTile(
    container: Container,
    glowLayer: Container,
    grid: TileGrid,
    tex: ReturnType<typeof tileTextures>,
    tx: number,
    ty: number
  ): boolean {
    const tile = grid.get(tx, ty);
    const put = (texture: Texture, alpha = 1): void => {
      const s = new Sprite(texture);
      s.position.set(tx * T, ty * T);
      s.alpha = alpha;
      container.addChild(s);
    };
    const isFace = (x: number, y: number): boolean => grid.get(x, y) === Tile.Wall && grid.isWalkable(x, y + 1);

    if (tile === Tile.Floor || tile === Tile.Door) {
      put(tex.floor[variantAt(tx, ty, tex.floor.length)]);
      const deco = grid.deco[grid.index(tx, ty)] as Deco;
      const decoTex = tex.deco[deco];
      if (decoTex) put(decoTex);
      if (deco === Deco.Glyph) this.addGlyphLight(glowLayer, tx, ty);
      if (tile === Tile.Door) put(tex.threshold);
      if (grid.get(tx, ty - 1) === Tile.Wall) put(tex.aoNorth);
      if (grid.get(tx - 1, ty) === Tile.Wall) put(tex.aoWest);
      if (grid.get(tx + 1, ty) === Tile.Wall) put(tex.aoEast);
      return true;
    }
    if (tile === Tile.Wall) {
      if (isFace(tx, ty)) put(tex.wallFace[variantAt(tx, ty, tex.wallFace.length)]);
      else put(isFace(tx, ty + 1) ? tex.wallCapLip : tex.wallCap);
      return true;
    }
    // Void directly above a wall face gets a cap, so outer walls have height.
    if (isFace(tx, ty + 1)) {
      put(tex.wallCapLip);
      return true;
    }
    return false;
  }

  private addGlyphLight(layer: Container, tx: number, ty: number): void {
    const glow = new Sprite(fxTextures().glow);
    glow.anchor.set(0.5);
    glow.position.set((tx + 0.5) * T, (ty + 0.5) * T);
    glow.width = glow.height = 56;
    glow.tint = this.accent;
    glow.blendMode = 'add';
    glow.alpha = 0.25;
    layer.addChild(glow);
    this.glyphs.push(glow);
  }

  /** Shows only chunks overlapping the view rectangle (world pixels) and animates doors. */
  update(dt: number, viewX: number, viewY: number, viewW: number, viewH: number): void {
    this.time += dt;
    const span = CHUNK * T;
    for (const chunk of this.chunks) {
      chunk.container.visible =
        chunk.x0 + span > viewX && chunk.x0 < viewX + viewW && chunk.y0 + span > viewY && chunk.y0 < viewY + viewH;
    }
    for (let i = 0; i < this.glyphs.length; i++) {
      this.glyphs[i].alpha = 0.18 + 0.12 * Math.sin(this.time * 1.7 + i * 1.3);
    }
    this.drawDoors();
  }

  private drawDoors(): void {
    const g = this.doors;
    g.clear();
    const grid = this.floor.grid;
    const pulse = 0.55 + 0.25 * Math.sin(this.time * 6);
    for (const room of this.floor.rooms) {
      for (const door of room.doors) {
        const first = door.tiles[0];
        if (!grid.isDoorLocked(first.x, first.y)) continue;
        const vertical = door.direction === 'east' || door.direction === 'west';
        for (const t of door.tiles) {
          g.rect(t.x * T, t.y * T, T, T).fill({ color: 0x000000, alpha: 0.35 });
          // Energy bars across the opening.
          for (let i = 0; i < 4; i++) {
            const o = 4 + i * 8;
            if (vertical) g.rect(t.x * T + 12, t.y * T + o - 2, 8, 3);
            else g.rect(t.x * T + o - 2, t.y * T + 12, 3, 8);
          }
          g.fill({ color: this.accent, alpha: pulse });
          if (vertical) g.rect(t.x * T + 15, t.y * T, 2, T);
          else g.rect(t.x * T, t.y * T + 15, T, 2);
          g.fill({ color: 0xffffff, alpha: pulse * 0.8 });
        }
      }
    }
  }

  destroy(): void {
    this.root.destroy({ children: true });
  }
}

/**
 * Draws everything that moves: player, enemies (with attack telegraphs),
 * projectiles, pickups and interactables. Sprites are keyed by sim entity id
 * and created or destroyed as entities come and go.
 *
 * Positions are interpolated between the last two sim steps so motion stays
 * smooth on displays faster than the 60 Hz simulation.
 */
import { AnimatedSprite, Container, Graphics, Sprite, type Texture } from 'pixi.js';
import type { Enemy, Interactable, Pickup, Projectile } from '../sim/entities';
import { slamRadius } from '../sim/enemies';
import type { World } from '../sim/world';
import { fxTextures } from './fxArt';
import { BIOME_ART, hex } from './palette';
import type { ActorSheet, Animation, SpriteLibrary } from './sheets';

interface ActorSprite {
  root: Container;
  body: AnimatedSprite;
  /** Add-blended copy of the body for hit flashes. */
  flash: AnimatedSprite;
  shadow: Graphics;
  current: Animation | undefined;
  baseScale: number;
}

interface Tracked {
  root: Container;
  seen: boolean;
}

const PLAYER_COLOR = 0x6fe7ff;
const ENEMY_SHOT_COLOR = 0xff5a7a;
const TELEGRAPH_COLOR = 0xff3b3b;

function makeShadow(width: number): Graphics {
  return new Graphics().ellipse(0, 0, width, width * 0.38).fill({ color: 0x000000, alpha: 0.38 });
}

function makeActor(sheet: ActorSheet, displayHeight: number): ActorSprite {
  const root = new Container();
  const shadow = makeShadow(displayHeight * 0.28);
  const body = new AnimatedSprite(sheet.idle.frames);
  body.anchor.set(sheet.originX, sheet.originY);
  const flash = new AnimatedSprite(sheet.idle.frames);
  flash.anchor.set(sheet.originX, sheet.originY);
  flash.blendMode = 'add';
  flash.alpha = 0;
  root.addChild(shadow, body, flash);
  const baseScale = displayHeight / sheet.frameHeight;
  return { root, body, flash, shadow, current: undefined, baseScale };
}

function play(actor: ActorSprite, anim: Animation): void {
  if (actor.current === anim) return;
  actor.current = anim;
  for (const s of [actor.body, actor.flash]) {
    s.textures = anim.frames;
    s.animationSpeed = anim.fps / 60;
    s.loop = anim.loop;
    s.gotoAndPlay(0);
  }
}

export class ActorView {
  /** Under actors: telegraphs, glows, interactables. */
  readonly ground = new Container();
  /** Actors, depth-sorted by feet position. */
  readonly actors = new Container();
  /** Over actors: projectiles and health bars. */
  readonly overlay = new Container();

  private readonly telegraphs = new Graphics();
  private readonly bars = new Graphics();
  private readonly player: ActorSprite;
  private readonly playerLight: Sprite;
  private readonly enemies = new Map<number, ActorSprite>();
  private readonly projectiles = new Map<number, Tracked>();
  private readonly pickups = new Map<number, Tracked>();
  private readonly interactables = new Map<number, Tracked>();
  private readonly previous = new Map<number, { x: number; y: number }>();
  private previousPlayer = { x: 0, y: 0 };
  private readonly accent: number;
  private time = 0;

  constructor(
    private readonly sprites: SpriteLibrary,
    private readonly world: World
  ) {
    this.actors.sortableChildren = true;
    this.accent = hex(BIOME_ART[world.plan.biome].accent);
    this.ground.addChild(this.telegraphs);
    this.player = makeActor(sprites.player, 56);
    this.actors.addChild(this.player.root);
    this.playerLight = this.glow(PLAYER_COLOR, 260, 0.16);
    this.ground.addChild(this.playerLight);
    this.overlay.addChild(this.bars);
    this.capture();
  }

  /** Records positions before a sim step, for interpolation. */
  capture(): void {
    const p = this.world.player;
    this.previousPlayer = { x: p.x, y: p.y };
    for (const e of this.world.enemies) this.previous.set(e.id, { x: e.x, y: e.y });
    for (const b of this.world.projectiles) this.previous.set(b.id, { x: b.x, y: b.y });
  }

  /** Interpolated player position, also used by the camera. */
  playerPosition(alpha: number): { x: number; y: number } {
    const p = this.world.player;
    const prev = this.previousPlayer;
    return { x: prev.x + (p.x - prev.x) * alpha, y: prev.y + (p.y - prev.y) * alpha };
  }

  private lerp(id: number, x: number, y: number, alpha: number): { x: number; y: number } {
    const prev = this.previous.get(id);
    if (!prev) return { x, y };
    return { x: prev.x + (x - prev.x) * alpha, y: prev.y + (y - prev.y) * alpha };
  }

  private glow(color: number, size: number, alpha: number): Sprite {
    const s = new Sprite(fxTextures().glow);
    s.anchor.set(0.5);
    s.width = s.height = size;
    s.tint = color;
    s.alpha = alpha;
    s.blendMode = 'add';
    return s;
  }

  update(dt: number, alpha: number): void {
    this.time += dt;
    this.telegraphs.clear();
    this.bars.clear();
    this.updatePlayer(alpha);
    this.syncEnemies(dt, alpha);
    this.syncProjectiles(alpha);
    this.syncPickups();
    this.syncInteractables();
  }

  private updatePlayer(alpha: number): void {
    const p = this.world.player;
    const a = this.player;
    const sheet = this.sprites.player;
    const pos = this.playerPosition(alpha);
    a.root.position.set(pos.x, pos.y);
    a.root.zIndex = pos.y;
    this.playerLight.position.set(pos.x, pos.y);

    const anim =
      p.action === 'dash' ? sheet.dash! : p.action === 'attack' ? sheet.attack : p.action === 'move' ? sheet.walk : sheet.idle;
    if (p.action === 'attack' && a.current === sheet.attack && p.swingTime < 0.02) a.current = undefined;
    play(a, anim);
    const facing = Math.cos(p.aim) < 0 ? -1 : 1;
    const squash = p.action === 'dash' ? 0.88 : 1;
    a.body.scale.set(a.baseScale * facing / squash, a.baseScale * squash);
    a.flash.scale.copyFrom(a.body.scale);
    a.flash.textures = a.body.textures;
    a.flash.currentFrame = a.body.currentFrame;
    // Hurt flash, then a blink while invulnerable.
    a.flash.alpha = p.hurtFlash > 0 ? 0.8 : 0;
    a.flash.tint = 0xff4040;
    const blinking = p.invulnerable > 0 && p.action !== 'dash' && Math.floor(this.time * 20) % 2 === 0;
    a.body.alpha = p.action === 'dead' ? Math.max(0.15, a.body.alpha - 0.02) : blinking ? 0.45 : p.action === 'dash' ? 0.7 : 1;
  }

  private syncEnemies(dt: number, alpha: number): void {
    const alive = new Set<number>();
    for (const e of this.world.enemies) {
      alive.add(e.id);
      let actor = this.enemies.get(e.id);
      if (!actor) {
        const sheet = this.sprites.enemies[e.def.sprite] ?? this.sprites.enemies.scavenger;
        actor = makeActor(sheet, e.def.displayHeight * (e.elite ? 1.15 : 1));
        if (e.elite) actor.root.addChildAt(this.glow(0xffc84a, e.radius * 5, 0.35), 0);
        this.enemies.set(e.id, actor);
        this.actors.addChild(actor.root);
      }
      this.drawEnemy(e, actor, dt, alpha);
    }
    for (const [id, actor] of this.enemies) {
      if (alive.has(id)) continue;
      actor.root.destroy({ children: true });
      this.enemies.delete(id);
      this.previous.delete(id);
    }
  }

  private drawEnemy(e: Enemy, a: ActorSprite, _dt: number, alpha: number): void {
    const sheet = this.sprites.enemies[e.def.sprite] ?? this.sprites.enemies.scavenger;
    const pos = this.lerp(e.id, e.x, e.y, alpha);
    a.root.position.set(pos.x, pos.y);
    a.root.zIndex = pos.y;

    const moving = e.state === 'chase';
    const anim =
      e.state === 'dying' ? sheet.death : e.state === 'windup' || e.state === 'attack' ? sheet.attack : moving ? sheet.walk : sheet.idle;
    play(a, anim);
    const facing = this.world.player.x < e.x ? -1 : 1;
    const bob = moving ? Math.abs(Math.sin(this.time * 9 + e.id)) * 0.06 : 0;
    // Windup: crouch and tremble; spawning: grow in.
    const windup = e.state === 'windup';
    const tremble = windup ? Math.sin(this.time * 60) * 1.2 : 0;
    const grow = e.state === 'spawning' ? Math.max(0.1, 1 - e.stateTime / 0.7) : 1;
    a.body.scale.set(a.baseScale * facing * grow * (windup ? 1.08 : 1), a.baseScale * grow * (1 + bob) * (windup ? 0.92 : 1));
    a.body.x = tremble;
    a.flash.scale.copyFrom(a.body.scale);
    a.flash.x = a.body.x;
    a.flash.textures = a.body.textures;
    a.flash.currentFrame = a.body.currentFrame;
    a.flash.tint = windup ? 0xff6a3a : 0xffffff;
    a.flash.alpha = e.flash > 0 ? 0.9 : windup ? 0.25 + 0.25 * Math.sin(this.time * 30) : 0;
    a.body.alpha = e.state === 'spawning' ? grow : e.state === 'dying' ? Math.max(0, e.stateTime / 0.5) : 1;
    a.shadow.alpha = a.body.alpha;

    if (e.state === 'spawning') this.drawSpawnRune(e, pos.x, pos.y);
    if (e.state === 'windup') this.drawTelegraph(e, pos.x, pos.y);
    if (!e.isBoss && e.health < e.maxHealth && e.state !== 'dying') this.drawHealthBar(e, pos.x, pos.y);
  }

  private drawSpawnRune(e: Enemy, x: number, y: number): void {
    const t = 1 - e.stateTime / 0.7;
    this.telegraphs.circle(x, y, e.radius * 2.2 * (0.5 + t * 0.5)).stroke({ width: 2, color: this.accent, alpha: 0.8 * (1 - t * 0.5) });
    this.telegraphs.circle(x, y, e.radius * 1.2 * t).fill({ color: this.accent, alpha: 0.18 });
  }

  /** Warning shapes during an enemy's windup; they fill in as the attack nears. */
  private drawTelegraph(e: Enemy, x: number, y: number): void {
    const g = this.telegraphs;
    const angle = Math.atan2(e.dirY, e.dirX);
    const urgency = 0.25 + 0.45 * Math.min(1, 1 - e.stateTime / 0.8);
    switch (e.attack) {
      case 'strike': {
        const reach = e.def.attackRange + 14 + e.radius;
        g.moveTo(x, y).arc(x, y, reach, angle - 0.95, angle + 0.95).lineTo(x, y).fill({ color: TELEGRAPH_COLOR, alpha: urgency * 0.5 });
        break;
      }
      case 'slam': {
        const r = slamRadius(e);
        g.circle(x, y, r).fill({ color: TELEGRAPH_COLOR, alpha: urgency * 0.35 });
        g.circle(x, y, r).stroke({ width: 2, color: TELEGRAPH_COLOR, alpha: 0.8 });
        break;
      }
      case 'lunge':
      case 'charge': {
        const length = e.attack === 'charge' ? 330 : 140;
        const w = e.radius * 1.6;
        const nx = -e.dirY * w;
        const ny = e.dirX * w;
        const ex = x + e.dirX * length;
        const ey = y + e.dirY * length;
        g.poly([x + nx, y + ny, ex + nx, ey + ny, ex - nx, ey - ny, x - nx, y - ny]).fill({ color: TELEGRAPH_COLOR, alpha: urgency * 0.4 });
        break;
      }
      case 'shot':
      case 'spread':
      case 'volley': {
        const offsets = e.attack === 'spread' ? [-0.32, 0, 0.32] : [0];
        for (const o of offsets) {
          g.moveTo(x, y)
            .lineTo(x + Math.cos(angle + o) * 260, y + Math.sin(angle + o) * 260)
            .stroke({ width: 2, color: TELEGRAPH_COLOR, alpha: urgency * 0.8 });
        }
        break;
      }
      case 'ring':
        g.circle(x, y, e.radius + 10 + (1 - e.stateTime) * 30).stroke({ width: 3, color: TELEGRAPH_COLOR, alpha: urgency });
        break;
      case 'summon':
        g.circle(x, y, 70).stroke({ width: 2, color: this.accent, alpha: urgency });
        break;
    }
  }

  private drawHealthBar(e: Enemy, x: number, y: number): void {
    const w = Math.max(24, e.radius * 2.2);
    const top = y - e.def.displayHeight * 0.95 - 6;
    this.bars.rect(x - w / 2 - 1, top - 1, w + 2, 5).fill({ color: 0x000000, alpha: 0.7 });
    this.bars.rect(x - w / 2, top, w * (e.health / e.maxHealth), 3).fill({ color: e.elite ? 0xffc84a : 0xff4d5e });
  }

  private syncProjectiles(alpha: number): void {
    const glowTex = fxTextures().glow;
    this.sync(this.projectiles, this.world.projectiles, this.overlay, (b: Projectile) => {
      const root = new Container();
      const color = b.owner === 'player' ? PLAYER_COLOR : ENEMY_SHOT_COLOR;
      const halo = new Sprite(glowTex);
      halo.anchor.set(0.5);
      halo.width = halo.height = b.radius * 7;
      halo.tint = color;
      halo.blendMode = 'add';
      const core = new Graphics().circle(0, 0, b.radius * 0.75).fill({ color: 0xffffff });
      root.addChild(halo, core);
      return root;
    }, (b, root) => {
      const pos = this.lerp(b.id, b.x, b.y, alpha);
      root.position.set(pos.x, pos.y);
      root.alpha = Math.min(1, b.life * 4);
    });
  }

  private syncPickups(): void {
    const ui = this.sprites.ui;
    this.sync(this.pickups, this.world.pickups, this.ground, (item: Pickup) => {
      const root = new Container();
      const color = item.kind === 'shard' ? 0xb89cff : item.kind === 'fragment' ? 0xffd98a : 0xff5a6a;
      root.addChild(this.glow(color, item.kind === 'fragment' ? 120 : 40, item.kind === 'fragment' ? 0.6 : 0.45));
      const texture: Texture | undefined =
        item.kind === 'shard' ? ui.fragment_shard : item.kind === 'fragment' ? ui.memory_fragment : ui.health;
      if (texture) {
        const s = new Sprite(texture);
        s.anchor.set(0.5);
        const size = item.kind === 'fragment' ? 30 : item.kind === 'shard' ? 14 : item.kind === 'potion' ? 22 : 16;
        s.width = s.height = size;
        root.addChild(s);
      }
      return root;
    }, (item, root) => {
      const bob = item.kind === 'fragment' ? Math.sin(this.time * 3) * 4 : 0;
      root.position.set(item.x, item.y + bob);
      if (item.kind === 'fragment') root.children[0].alpha = 0.45 + 0.25 * Math.sin(this.time * 4);
    });
  }

  private syncInteractables(): void {
    const props = this.sprites.props;
    this.sync(this.interactables, this.world.interactables, this.actors, (it: Interactable) => {
      const root = new Container();
      if (it.kind === 'portal') {
        root.addChild(this.glow(this.accent, 220, 0.7));
        const rift = new Sprite(props.void_rift);
        rift.anchor.set(0.5);
        rift.width = rift.height = 84;
        root.addChild(rift);
      } else {
        root.addChild(makeShadow(26));
        root.addChild(this.glow(it.kind === 'chest' ? 0xffd98a : this.accent, 140, 0.35));
        const s = new Sprite(it.kind === 'chest' ? props.memory_chest : props.memory_fountain);
        s.anchor.set(0.5, 0.82);
        s.width = s.height = it.kind === 'chest' ? 64 : 84;
        root.addChild(s);
      }
      return root;
    }, (it, root) => {
      root.position.set(it.x, it.y);
      root.zIndex = it.y;
      if (it.kind === 'portal') {
        root.children[1].rotation = this.time * 0.8;
        root.children[0].alpha = 0.55 + 0.2 * Math.sin(this.time * 3);
      } else {
        // Spent chests and wells go dark.
        root.children[1].alpha = it.used ? 0 : 0.3 + 0.12 * Math.sin(this.time * 2.5);
        root.children[2].alpha = it.used ? 0.55 : 1;
      }
    });
  }

  /** Creates, updates and removes display objects to mirror an entity list. */
  private sync<T extends { id: number }>(
    tracked: Map<number, Tracked>,
    items: readonly T[],
    layer: Container,
    create: (item: T) => Container,
    update: (item: T, root: Container) => void
  ): void {
    for (const t of tracked.values()) t.seen = false;
    for (const item of items) {
      let t = tracked.get(item.id);
      if (!t) {
        t = { root: create(item), seen: true };
        tracked.set(item.id, t);
        layer.addChild(t.root);
      }
      t.seen = true;
      update(item, t.root);
    }
    for (const [id, t] of tracked) {
      if (t.seen) continue;
      t.root.destroy({ children: true });
      tracked.delete(id);
      this.previous.delete(id);
    }
  }

  destroy(): void {
    for (const layer of [this.ground, this.actors, this.overlay]) layer.destroy({ children: true });
  }
}

/**
 * Transient visual effects driven by sim events: particles, slash arcs,
 * shockwave rings, damage numbers and camera shake. Everything is pooled or
 * short-lived, and nothing here feeds back into the simulation.
 */
import { Container, Graphics, Sprite, Text } from 'pixi.js';
import type { SimEvent } from '../sim/events';
import { fxTextures } from './fxArt';

interface Particle {
  sprite: Sprite;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  drag: number;
  grow: number;
}

interface Slash {
  x: number;
  y: number;
  angle: number;
  combo: number;
  age: number;
}

interface Ring {
  sprite: Sprite;
  age: number;
  life: number;
  radius: number;
}

interface FloatingText {
  text: Text;
  vy: number;
  age: number;
  life: number;
}

const MAX_PARTICLES = 500;
const SLASH_LIFE = 0.16;
const MOTES = 40;

export class Effects {
  /** World-space layer above actors. */
  readonly layer = new Container();
  private readonly slashGfx = new Graphics();
  private readonly particles: Particle[] = [];
  private readonly free: Sprite[] = [];
  private readonly slashes: Slash[] = [];
  private readonly rings: Ring[] = [];
  private readonly texts: FloatingText[] = [];
  private readonly motes: Particle[] = [];
  private shake = 0;
  /** 0..1 strength of the red screen flash after taking damage. */
  hurtFlash = 0;

  constructor(
    private readonly accent: number,
    private readonly random: () => number = Math.random
  ) {
    this.layer.addChild(this.slashGfx);
  }

  handle(events: readonly SimEvent[], playerX: number, playerY: number): void {
    for (const e of events) {
      switch (e.type) {
        case 'swing':
          this.slashes.push({ x: e.x, y: e.y, angle: e.angle, combo: e.combo, age: 0 });
          break;
        case 'dash':
          this.burst(e.x, e.y, 0x6fe7ff, 10, 60, 0.35, 5);
          break;
        case 'bolt':
          this.burst(e.x + Math.cos(e.angle) * 16, e.y + Math.sin(e.angle) * 16, 0x6fe7ff, 5, 90, 0.2, 3);
          break;
        case 'hit':
          if (e.target === 'enemy') {
            this.directionalSparks(e.x, e.y, Math.atan2(e.y - playerY, e.x - playerX), e.crit ? 14 : 7);
            this.number(e.x, e.y, `${e.amount}`, e.crit ? 0xffd34a : 0xffffff, e.crit ? 22 : 16);
          } else {
            this.burst(e.x, e.y, 0xff3b3b, 12, 140, 0.4, 4);
            this.number(e.x, e.y, `-${e.amount}`, 0xff5a5a, 18);
          }
          break;
        case 'shockwave':
          this.ring(e.x, e.y, e.radius, 0x6fe7ff, 0.3);
          break;
        case 'enemyAttack':
          if (e.attack === 'slam') this.ring(e.x, e.y, 120, 0xff6a3a, 0.35);
          break;
        case 'enemyDied':
          this.burst(e.x, e.y - 16, this.accent, e.boss ? 80 : 18, e.boss ? 260 : 150, e.boss ? 1.2 : 0.6, e.boss ? 8 : 5);
          if (e.boss) this.ring(e.x, e.y, 260, 0xffffff, 0.6);
          break;
        case 'enemySpawned':
          this.burst(e.x, e.y, this.accent, 8, 50, 0.5, 4);
          break;
        case 'pickup':
          this.burst(e.x, e.y, e.kind === 'shard' ? 0xb89cff : e.kind === 'fragment' ? 0xffd98a : 0xff5a6a, 5, 60, 0.3, 3);
          break;
        case 'fragmentFound':
          this.ring(playerX, playerY, 140, 0xffd98a, 0.7);
          break;
        case 'potion':
          this.burst(playerX, playerY, 0x7dff9a, 16, 80, 0.6, 4);
          this.number(playerX, playerY - 30, `+${e.healed}`, 0x7dff9a, 18);
          break;
        case 'levelUp':
          this.ring(playerX, playerY, 120, 0xffd98a, 0.6);
          this.number(playerX, playerY - 40, 'LEVEL UP', 0xffd98a, 20);
          break;
        case 'interact':
          this.burst(e.x, e.y, 0xffd98a, 24, 120, 0.8, 5);
          break;
        case 'playerHurt':
          this.hurtFlash = 1;
          break;
        case 'shake':
          this.shake = Math.min(18, Math.max(this.shake, e.strength));
          break;
        default:
          break;
      }
    }
  }

  /** Camera offset for this frame's shake. */
  shakeOffset(): { x: number; y: number } {
    if (this.shake < 0.2) return { x: 0, y: 0 };
    return { x: (this.random() * 2 - 1) * this.shake, y: (this.random() * 2 - 1) * this.shake };
  }

  update(dt: number, view: { x: number; y: number; w: number; h: number }): void {
    this.shake *= Math.exp(-14 * dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 3);
    this.updateParticles(dt);
    this.updateSlashes(dt);
    this.updateRings(dt);
    this.updateTexts(dt);
    this.updateMotes(dt, view);
  }

  private spawn(x: number, y: number, color: number, size: number, vx: number, vy: number, life: number, drag = 4): void {
    if (this.particles.length >= MAX_PARTICLES) return;
    const sprite = this.free.pop() ?? new Sprite(fxTextures().spark);
    sprite.anchor.set(0.5);
    sprite.blendMode = 'add';
    sprite.tint = color;
    sprite.position.set(x, y);
    sprite.width = sprite.height = size;
    sprite.alpha = 1;
    sprite.visible = true;
    if (!sprite.parent) this.layer.addChild(sprite);
    this.particles.push({ sprite, vx, vy, life, maxLife: life, drag, grow: 0 });
  }

  private burst(x: number, y: number, color: number, count: number, speed: number, life: number, size: number): void {
    for (let i = 0; i < count; i++) {
      const a = this.random() * Math.PI * 2;
      const s = speed * (0.3 + this.random() * 0.7);
      this.spawn(x, y, color, size * (0.6 + this.random() * 0.8), Math.cos(a) * s, Math.sin(a) * s, life * (0.6 + this.random() * 0.6));
    }
  }

  private directionalSparks(x: number, y: number, angle: number, count: number): void {
    for (let i = 0; i < count; i++) {
      const a = angle + (this.random() - 0.5) * 1.4;
      const s = 120 + this.random() * 220;
      this.spawn(x, y, i % 3 === 0 ? 0xffffff : 0xffc46a, 3 + this.random() * 3, Math.cos(a) * s, Math.sin(a) * s, 0.25 + this.random() * 0.2, 7);
    }
  }

  private ring(x: number, y: number, radius: number, color: number, life: number): void {
    const sprite = new Sprite(fxTextures().ring);
    sprite.anchor.set(0.5);
    sprite.position.set(x, y);
    sprite.tint = color;
    sprite.blendMode = 'add';
    this.layer.addChild(sprite);
    this.rings.push({ sprite, age: 0, life, radius });
  }

  private number(x: number, y: number, label: string, color: number, size: number): void {
    const text = new Text({
      text: label,
      style: { fontFamily: 'Cinzel, Georgia, serif', fontSize: size, fontWeight: '700', fill: color, stroke: { color: 0x000000, width: 4 } },
    });
    text.anchor.set(0.5);
    text.position.set(x + (this.random() - 0.5) * 14, y);
    text.resolution = 2;
    this.layer.addChild(text);
    this.texts.push({ text, vy: -70, age: 0, life: 0.8 });
  }

  private updateParticles(dt: number): void {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        p.sprite.visible = false;
        this.free.push(p.sprite);
        this.particles.splice(i, 1);
        continue;
      }
      const decay = Math.exp(-p.drag * dt);
      p.vx *= decay;
      p.vy *= decay;
      p.sprite.x += p.vx * dt;
      p.sprite.y += p.vy * dt;
      p.sprite.alpha = p.life / p.maxLife;
    }
  }

  private updateSlashes(dt: number): void {
    const g = this.slashGfx;
    g.clear();
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.age += dt;
      if (s.age >= SLASH_LIFE) {
        this.slashes.splice(i, 1);
        continue;
      }
      const t = s.age / SLASH_LIFE;
      const finisher = s.combo === 2;
      const reach = finisher ? 68 : 58;
      const half = finisher ? 1.45 : 1.0;
      // The crescent sweeps across the arc; alternate swing direction per combo step.
      const dir = s.combo === 1 ? -1 : 1;
      const sweep = -half + 2 * half * Math.min(1, t * 1.8);
      const from = s.angle - half * dir;
      const to = s.angle + sweep * dir;
      const alpha = 1 - t;
      const steps = 10;
      const outer: number[] = [];
      const inner: number[] = [];
      for (let k = 0; k <= steps; k++) {
        const a = from + ((to - from) * k) / steps;
        const thickness = 6 + 14 * Math.sin((k / steps) * Math.PI);
        outer.push(s.x + Math.cos(a) * reach, s.y + Math.sin(a) * reach);
        inner.push(s.x + Math.cos(a) * (reach - thickness), s.y + Math.sin(a) * (reach - thickness));
      }
      const points = [...outer];
      for (let k = inner.length - 2; k >= 0; k -= 2) points.push(inner[k], inner[k + 1]);
      g.poly(points).fill({ color: finisher ? 0xfff3c4 : 0xc8f7ff, alpha: 0.85 * alpha });
      g.poly(outer, false).stroke({ width: 2, color: 0xffffff, alpha });
    }
  }

  private updateRings(dt: number): void {
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.age += dt;
      const t = r.age / r.life;
      if (t >= 1) {
        r.sprite.destroy();
        this.rings.splice(i, 1);
        continue;
      }
      const size = r.radius * 2 * (0.3 + 0.7 * Math.sqrt(t));
      r.sprite.width = r.sprite.height = size;
      r.sprite.alpha = 1 - t;
    }
  }

  private updateTexts(dt: number): void {
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const f = this.texts[i];
      f.age += dt;
      if (f.age >= f.life) {
        f.text.destroy();
        this.texts.splice(i, 1);
        continue;
      }
      f.vy *= Math.exp(-3 * dt);
      f.text.y += f.vy * dt;
      const t = f.age / f.life;
      f.text.alpha = t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3;
      f.text.scale.set(t < 0.1 ? 0.6 + 4 * t : 1);
    }
  }

  /** Slow drifting dust around the camera for atmosphere. */
  private updateMotes(dt: number, view: { x: number; y: number; w: number; h: number }): void {
    while (this.motes.length < MOTES) {
      const sprite = new Sprite(fxTextures().spark);
      sprite.anchor.set(0.5);
      sprite.blendMode = 'add';
      sprite.tint = this.accent;
      this.layer.addChildAt(sprite, 0);
      const mote: Particle = { sprite, vx: 0, vy: 0, life: 0, maxLife: 1, drag: 0, grow: 0 };
      this.resetMote(mote, view);
      mote.life = this.random() * mote.maxLife;
      this.motes.push(mote);
    }
    for (const m of this.motes) {
      m.life -= dt;
      const s = m.sprite;
      s.x += m.vx * dt;
      s.y += m.vy * dt;
      const outside = s.x < view.x - 40 || s.x > view.x + view.w + 40 || s.y < view.y - 40 || s.y > view.y + view.h + 40;
      if (m.life <= 0 || outside) this.resetMote(m, view);
      const t = m.life / m.maxLife;
      s.alpha = 0.35 * Math.sin(t * Math.PI);
    }
  }

  private resetMote(m: Particle, view: { x: number; y: number; w: number; h: number }): void {
    m.sprite.position.set(view.x + this.random() * view.w, view.y + this.random() * view.h);
    m.vx = (this.random() - 0.5) * 14;
    m.vy = -6 - this.random() * 12;
    m.maxLife = 3 + this.random() * 4;
    m.life = m.maxLife;
    m.sprite.width = m.sprite.height = 2 + this.random() * 3;
  }

  destroy(): void {
    this.layer.destroy({ children: true });
  }
}

/**
 * The Pixi renderer: owns the application, the layer stack and the camera.
 *
 * Layers, bottom to top: level tiles, ground (telegraphs, glows), actors
 * (depth-sorted), effects, overlay (projectiles, bars), then screen-space
 * darkness and the hurt flash.
 */
import { Application, Container, Graphics, Sprite } from 'pixi.js';
import type { SimEvent } from '../sim/events';
import type { World } from '../sim/world';
import { ActorView } from './ActorView';
import { Effects } from './Effects';
import { fxTextures } from './fxArt';
import { LevelView } from './LevelView';
import { BIOME_ART, hex } from './palette';
import { loadSprites, type SpriteLibrary } from './sheets';

/** World pixels visible vertically; the zoom follows the window height. */
const VIEW_HEIGHT = 520;
const LOOK_AHEAD = 0.18;
const LOOK_AHEAD_MAX = 90;

interface FloorScene {
  world: World;
  level: LevelView;
  actors: ActorView;
  effects: Effects;
}

export class Renderer {
  private readonly app = new Application();
  private readonly camera = new Container();
  private readonly darkness = new Sprite();
  private readonly flash = new Graphics();
  private sprites!: SpriteLibrary;
  private scene: FloorScene | undefined;
  private camX = 0;
  private camY = 0;
  private zoom = 1;
  private aimX = 0;
  private aimY = 0;

  async init(host: HTMLElement, onProgress?: (fraction: number) => void): Promise<void> {
    await this.app.init({
      resizeTo: window,
      background: 0x000000,
      antialias: false,
      autoDensity: true,
      resolution: Math.min(window.devicePixelRatio || 1, 2),
      powerPreference: 'high-performance',
    });
    this.app.ticker.stop();
    host.prepend(this.app.canvas);
    this.app.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.darkness.texture = fxTextures().vignette;
    this.darkness.anchor.set(0.5);
    this.app.stage.addChild(this.camera, this.darkness, this.flash);
    this.sprites = await loadSprites(onProgress);
  }

  get canvas(): HTMLCanvasElement {
    return this.app.canvas;
  }

  /** Builds the scene for a new floor, discarding the previous one. */
  showFloor(world: World): void {
    this.clearFloor();
    const biome = world.plan.biome;
    const art = BIOME_ART[biome];
    this.app.renderer.background.color = art.background;
    const level = new LevelView(world.floor, biome);
    const actors = new ActorView(this.sprites, world);
    const effects = new Effects(hex(art.accent));
    this.camera.addChild(level.root, actors.ground, actors.actors, effects.layer, actors.overlay);
    this.scene = { world, level, actors, effects };
    this.camX = world.player.x;
    this.camY = world.player.y;
    this.darkness.alpha = art.darkness;
  }

  clearFloor(): void {
    if (!this.scene) return;
    this.scene.level.destroy();
    this.scene.actors.destroy();
    this.scene.effects.destroy();
    this.camera.removeChildren();
    this.scene = undefined;
  }

  /** Call before each sim step so motion can be interpolated. */
  beforeStep(): void {
    this.scene?.actors.capture();
  }

  handleEvents(events: readonly SimEvent[]): void {
    if (!this.scene) return;
    const p = this.scene.world.player;
    this.scene.effects.handle(events, p.x, p.y);
  }

  /** Mouse position in screen pixels, used for camera look-ahead. */
  setAimScreen(x: number, y: number): void {
    this.aimX = x;
    this.aimY = y;
  }

  screenToWorld(x: number, y: number): { x: number; y: number } {
    const w = this.app.screen.width;
    const h = this.app.screen.height;
    return { x: (x - w / 2) / this.zoom + this.camX, y: (y - h / 2) / this.zoom + this.camY };
  }

  /**
   * Draws a frame. `alpha` is how far real time is between the last two sim
   * steps (0..1); `dt` is the real seconds since the previous frame.
   */
  render(alpha: number, dt: number): void {
    const scene = this.scene;
    if (scene) this.updateScene(scene, alpha, dt);
    this.app.renderer.render(this.app.stage);
  }

  private updateScene(scene: FloorScene, alpha: number, dt: number): void {
    const w = this.app.screen.width;
    const h = this.app.screen.height;
    this.zoom = Math.max(1, h / VIEW_HEIGHT);

    const target = scene.actors.playerPosition(alpha);
    // Lean the camera toward the cursor so the player sees where they aim.
    const lookX = Math.max(-LOOK_AHEAD_MAX, Math.min(LOOK_AHEAD_MAX, ((this.aimX - w / 2) / this.zoom) * LOOK_AHEAD));
    const lookY = Math.max(-LOOK_AHEAD_MAX, Math.min(LOOK_AHEAD_MAX, ((this.aimY - h / 2) / this.zoom) * LOOK_AHEAD));
    const follow = 1 - Math.exp(-10 * dt);
    this.camX += (target.x + lookX - this.camX) * follow;
    this.camY += (target.y + lookY - this.camY) * follow;

    const shake = scene.effects.shakeOffset();
    this.camera.scale.set(this.zoom);
    this.camera.position.set(Math.round(w / 2 - (this.camX + shake.x) * this.zoom), Math.round(h / 2 - (this.camY + shake.y) * this.zoom));

    const viewW = w / this.zoom;
    const viewH = h / this.zoom;
    const view = { x: this.camX - viewW / 2, y: this.camY - viewH / 2, w: viewW, h: viewH };
    scene.level.update(dt, view.x - 64, view.y - 64, view.w + 128, view.h + 128);
    scene.actors.update(dt, alpha);
    scene.effects.update(dt, view);

    // Darkness centred on the player, sized to the larger screen side.
    const px = w / 2 + (target.x - this.camX) * this.zoom;
    const py = h / 2 + (target.y - this.camY) * this.zoom;
    const size = Math.max(w, h) * 1.9;
    this.darkness.position.set(px, py);
    this.darkness.width = this.darkness.height = size;

    this.flash.clear();
    if (scene.effects.hurtFlash > 0) this.flash.rect(0, 0, w, h).fill({ color: 0xff2020, alpha: scene.effects.hurtFlash * 0.22 });
  }
}

/**
 * Keyboard, mouse and gamepad input, turned into one InputFrame per sim step.
 *
 * Held buttons (move, attack, bolt) are sampled; one-shot actions (dash,
 * potion, interact) latch until a sim step consumes them, so a tap between
 * two steps is never lost.
 */
import type { InputFrame } from '../sim/entities';

export type MenuAction = 'pause' | 'confirm' | 'map';

const KEYS = {
  up: ['KeyW', 'ArrowUp'],
  down: ['KeyS', 'ArrowDown'],
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  attack: ['KeyJ'],
  bolt: ['KeyK'],
  dash: ['Space', 'ShiftLeft', 'ShiftRight'],
  potion: ['KeyQ'],
  interact: ['KeyE', 'KeyF'],
} as const;

const STICK_DEADZONE = 0.22;

export class Input {
  private readonly held = new Set<string>();
  private mouseX = 0;
  private mouseY = 0;
  private mouseLeft = false;
  private mouseRight = false;
  private latched = { dash: false, potion: false, interact: false };
  private padButtons: boolean[] = [];
  private padAim: { x: number; y: number } | undefined;
  /** True after the last aim came from a gamepad stick rather than the mouse. */
  private usingPad = false;

  constructor(
    target: HTMLElement,
    private readonly onMenu: (action: MenuAction) => void
  ) {
    window.addEventListener('keydown', (e) => this.keyDown(e));
    window.addEventListener('keyup', (e) => this.held.delete(e.code));
    window.addEventListener('blur', () => this.releaseAll());
    target.addEventListener('mousemove', (e) => {
      this.mouseX = e.clientX;
      this.mouseY = e.clientY;
      this.usingPad = false;
    });
    target.addEventListener('mousedown', (e) => {
      if (e.button === 0) this.mouseLeft = true;
      if (e.button === 2) this.mouseRight = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.mouseLeft = false;
      if (e.button === 2) this.mouseRight = false;
    });
  }

  get mouse(): { x: number; y: number } {
    return { x: this.mouseX, y: this.mouseY };
  }

  private keyDown(e: KeyboardEvent): void {
    // Keep Space/arrows from scrolling and Tab from leaving the canvas.
    if (['Space', 'Tab', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
    if (e.repeat) return;
    this.held.add(e.code);
    if (KEYS.dash.includes(e.code as never)) this.latched.dash = true;
    if (KEYS.potion.includes(e.code as never)) this.latched.potion = true;
    if (KEYS.interact.includes(e.code as never)) this.latched.interact = true;
    if (e.code === 'Escape' || e.code === 'KeyP') this.onMenu('pause');
    if (e.code === 'Tab' || e.code === 'KeyM') this.onMenu('map');
    if (e.code === 'Enter') this.onMenu('confirm');
  }

  /** Drops held state, e.g. when the window loses focus or a menu opens. */
  releaseAll(): void {
    this.held.clear();
    this.mouseLeft = false;
    this.mouseRight = false;
    this.latched = { dash: false, potion: false, interact: false };
  }

  private any(codes: readonly string[]): boolean {
    return codes.some((c) => this.held.has(c));
  }

  /** Reads gamepad state once per animation frame; latches its one-shot buttons. */
  pollGamepad(): void {
    const pad = navigator.getGamepads?.().find((p) => p?.connected);
    if (!pad) {
      this.padAim = undefined;
      return;
    }
    const pressed = pad.buttons.map((b) => b.pressed);
    const edge = (i: number): boolean => !!pressed[i] && !this.padButtons[i];
    if (edge(0) || edge(5)) this.latched.dash = true; // A / RB
    if (edge(2)) this.latched.potion = true; // X
    if (edge(3)) this.latched.interact = true; // Y
    if (edge(9)) this.onMenu('pause'); // Start
    if (edge(8)) this.onMenu('map'); // Back
    if (edge(1)) this.onMenu('confirm'); // B
    this.padButtons = pressed;
    const rx = pad.axes[2] ?? 0;
    const ry = pad.axes[3] ?? 0;
    if (Math.hypot(rx, ry) > STICK_DEADZONE) {
      this.padAim = { x: rx, y: ry };
      this.usingPad = true;
    }
  }

  /**
   * Builds the frame for one sim step and clears the one-shot latches.
   * `toWorld` maps screen pixels to world pixels for mouse aiming.
   */
  frame(playerX: number, playerY: number, toWorld: (x: number, y: number) => { x: number; y: number }): InputFrame {
    const pad = navigator.getGamepads?.().find((p) => p?.connected);
    let moveX = (this.any(KEYS.right) ? 1 : 0) - (this.any(KEYS.left) ? 1 : 0);
    let moveY = (this.any(KEYS.down) ? 1 : 0) - (this.any(KEYS.up) ? 1 : 0);
    if (pad && Math.hypot(pad.axes[0] ?? 0, pad.axes[1] ?? 0) > STICK_DEADZONE) {
      moveX = pad.axes[0];
      moveY = pad.axes[1];
    }

    let aim = toWorld(this.mouseX, this.mouseY);
    if (this.usingPad) {
      const dir = this.padAim ?? (Math.hypot(moveX, moveY) > 0 ? { x: moveX, y: moveY } : { x: 1, y: 0 });
      aim = { x: playerX + dir.x * 100, y: playerY + dir.y * 100 };
    }

    const padHeld = (i: number): boolean => !!pad?.buttons[i]?.pressed;
    const frame: InputFrame = {
      moveX,
      moveY,
      aimX: aim.x,
      aimY: aim.y,
      attack: this.mouseLeft || this.any(KEYS.attack) || padHeld(7),
      bolt: this.mouseRight || this.any(KEYS.bolt) || padHeld(6),
      dash: this.latched.dash,
      potion: this.latched.potion,
      interact: this.latched.interact,
    };
    this.latched = { dash: false, potion: false, interact: false };
    return frame;
  }
}

/**
 * Persistent state in localStorage.
 *
 * - Meta progress survives every run: memory fragments recovered, records
 *   and settings. Fragments are kept even when a run ends in death; that is
 *   the game's long-term progression.
 * - The run snapshot is written at the start of each floor, so "Continue"
 *   resumes at that floor's entrance.
 *
 * Storage can be missing (private mode) or full; every access is guarded and
 * the game keeps working without persistence.
 */
import { z } from 'zod';
import { restoreRun, type RunState } from '../sim/run';

const META_KEY = 'memory-reconstruction.meta.v1';
const RUN_KEY = 'memory-reconstruction.run.v1';

const SettingsSchema = z.object({
  masterVolume: z.number().min(0).max(1),
  musicVolume: z.number().min(0).max(1),
  sfxVolume: z.number().min(0).max(1),
  screenShake: z.boolean(),
});

const MetaSchema = z.object({
  version: z.literal(1),
  fragments: z.array(z.string()),
  runs: z.number().int().min(0),
  victories: z.number().int().min(0),
  bestDepth: z.number().int().min(0),
  settings: SettingsSchema,
});

export type Settings = z.infer<typeof SettingsSchema>;
export type Meta = z.infer<typeof MetaSchema>;

export function defaultMeta(): Meta {
  return {
    version: 1,
    fragments: [],
    runs: 0,
    victories: 0,
    bestDepth: 0,
    settings: { masterVolume: 0.8, musicVolume: 0.5, sfxVolume: 0.8, screenShake: true },
  };
}

/** The subset of Storage the store needs; tests pass an in-memory map. */
export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

function browserStorage(): KeyValueStore | undefined {
  try {
    return typeof window !== 'undefined' ? window.localStorage : undefined;
  } catch {
    return undefined;
  }
}

export class SaveStore {
  constructor(private readonly storage: KeyValueStore | undefined = browserStorage()) {}

  private read(key: string): unknown {
    try {
      const raw = this.storage?.getItem(key);
      return raw ? (JSON.parse(raw) as unknown) : undefined;
    } catch {
      return undefined;
    }
  }

  private write(key: string, value: unknown): boolean {
    try {
      this.storage?.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }

  loadMeta(): Meta {
    const parsed = MetaSchema.safeParse(this.read(META_KEY));
    return parsed.success ? parsed.data : defaultMeta();
  }

  saveMeta(meta: Meta): boolean {
    return this.write(META_KEY, meta);
  }

  loadRun(): RunState | undefined {
    return restoreRun(this.read(RUN_KEY));
  }

  hasRun(): boolean {
    return this.loadRun() !== undefined;
  }

  saveRun(run: RunState): boolean {
    return this.write(RUN_KEY, run);
  }

  clearRun(): void {
    try {
      this.storage?.removeItem(RUN_KEY);
    } catch {
      // Nothing to clear when storage is unavailable.
    }
  }
}

/** Adds a run's fragments and records into the meta progress (pure). */
export function recordRun(meta: Meta, run: RunState, won: boolean): Meta {
  const fragments = Array.from(new Set([...meta.fragments, ...run.fragmentsFound]));
  return {
    ...meta,
    fragments,
    runs: meta.runs + 1,
    victories: meta.victories + (won ? 1 : 0),
    bestDepth: Math.max(meta.bestDepth, run.depth + 1),
  };
}

/**
 * Synthesized sound: short procedural effects for sim events and a quiet
 * generative ambience per biome. Nothing is loaded from disk.
 *
 * Browsers only allow audio after a user gesture, so the context is created
 * on the first `unlock()` call (the title screen's first click or key).
 */
import type { BiomeId } from '../sim/content';
import type { SimEvent } from '../sim/events';

/** Pentatonic-ish scale roots per biome, in Hz, for the ambient pad. */
const BIOME_ROOTS: Record<BiomeId, number> = {
  ruins: 110,
  forest: 123.47,
  caves: 98,
  crystal: 130.81,
  void: 87.31,
  sanctuary: 146.83,
};
const SCALE = [1, 9 / 8, 5 / 4, 3 / 2, 5 / 3, 2];

export class Sound {
  private ctx: AudioContext | undefined;
  private master!: GainNode;
  private sfx!: GainNode;
  private music!: GainNode;
  private noise!: AudioBuffer;
  private ambience: { stop(): void } | undefined;
  private ambienceKey = '';
  private volumes = { master: 0.8, music: 0.5, sfx: 0.8 };
  private lastPlayed = new Map<string, number>();

  /** Creates the audio context; call from a user gesture. Safe to call repeatedly. */
  unlock(): void {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return;
    }
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    this.ctx = new Ctor();
    this.master = this.ctx.createGain();
    this.sfx = this.ctx.createGain();
    this.music = this.ctx.createGain();
    this.sfx.connect(this.master);
    this.music.connect(this.master);
    this.master.connect(this.ctx.destination);
    this.noise = this.ctx.createBuffer(1, this.ctx.sampleRate, this.ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    this.applyVolumes();
  }

  setVolumes(master: number, music: number, sfx: number): void {
    this.volumes = { master, music, sfx };
    this.applyVolumes();
  }

  private applyVolumes(): void {
    if (!this.ctx) return;
    this.master.gain.value = this.volumes.master;
    this.music.gain.value = this.volumes.music * 0.5;
    this.sfx.gain.value = this.volumes.sfx * 0.6;
  }

  /** Suspends or resumes all audio (e.g. while paused in the background). */
  setSuspended(suspended: boolean): void {
    if (!this.ctx) return;
    void (suspended ? this.ctx.suspend() : this.ctx.resume());
  }

  handle(events: readonly SimEvent[]): void {
    for (const e of events) {
      switch (e.type) {
        case 'swing':
          this.whoosh(e.combo === 2 ? 0.16 : 0.1, e.combo === 2 ? 900 : 1600, 0.25);
          break;
        case 'hit':
          if (e.target === 'enemy') this.thump(e.crit ? 220 : 160, e.crit ? 0.35 : 0.22, 'hit');
          break;
        case 'playerHurt':
          this.tone(180, 70, 0.22, 'sawtooth', 0.3);
          this.thump(90, 0.4, 'hurt');
          break;
        case 'dash':
          this.whoosh(0.18, 600, 0.2);
          break;
        case 'bolt':
          this.tone(1200, 500, 0.12, 'square', 0.08);
          break;
        case 'enemyWindup':
          this.tone(260, 420, 0.25, 'triangle', 0.06, 'windup');
          break;
        case 'enemyAttack':
          if (e.attack === 'slam') this.thump(60, 0.5, 'slam');
          else if (e.attack === 'ring' || e.attack === 'spread' || e.attack === 'shot') this.tone(700, 300, 0.15, 'sine', 0.08, 'shot');
          break;
        case 'enemyDied':
          this.tone(e.boss ? 200 : 420, e.boss ? 40 : 120, e.boss ? 1.2 : 0.25, 'triangle', e.boss ? 0.4 : 0.12);
          this.whoosh(e.boss ? 0.8 : 0.15, 400, 0.2);
          break;
        case 'pickup':
          if (e.kind === 'shard') this.tone(1300 + Math.random() * 300, 1800, 0.06, 'sine', 0.06, 'shard');
          else this.chord([660, 880], 0.25, 0.1);
          break;
        case 'potion':
          this.chord([392, 494, 587], 0.4, 0.12);
          break;
        case 'levelUp':
          this.arpeggio([523, 659, 784, 1047], 0.07, 0.14);
          break;
        case 'roomLocked':
          this.thump(70, 0.5, 'lock');
          this.tone(110, 108, 0.8, 'sawtooth', 0.06);
          break;
        case 'roomCleared':
          this.arpeggio([392, 523, 659], 0.09, 0.12);
          break;
        case 'bossIntro':
          this.tone(55, 50, 2.5, 'sawtooth', 0.18);
          this.tone(82, 80, 2.5, 'sine', 0.2);
          break;
        case 'bossPhase':
          this.tone(80, 160, 0.6, 'sawtooth', 0.15);
          break;
        case 'fragmentFound':
          this.arpeggio([784, 988, 1175, 1568], 0.11, 0.12);
          break;
        case 'interact':
          this.chord([440, 554, 659], 0.6, 0.12);
          break;
        case 'notice':
          this.tone(300, 260, 0.15, 'square', 0.05);
          break;
        case 'playerDied':
          this.arpeggio([392, 330, 262, 196], 0.18, 0.15);
          break;
        case 'victory':
          this.arpeggio([523, 659, 784, 1047, 1319], 0.16, 0.15);
          break;
        default:
          break;
      }
    }
  }

  /** Plays a menu click. */
  click(): void {
    this.tone(880, 990, 0.05, 'sine', 0.06);
  }

  /** Throttles a named sound so a crowd of identical events doesn't clip. */
  private throttled(key: string | undefined, gap = 0.04): boolean {
    if (!this.ctx || !key) return false;
    const now = this.ctx.currentTime;
    if (now - (this.lastPlayed.get(key) ?? -1) < gap) return true;
    this.lastPlayed.set(key, now);
    return false;
  }

  private envelope(gain: GainNode, peak: number, duration: number, start: number): void {
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(peak, start + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  }

  private tone(from: number, to: number, duration: number, type: OscillatorType, volume: number, key?: string): void {
    const ctx = this.ctx;
    if (!ctx || this.throttled(key)) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(from, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + duration);
    this.envelope(gain, volume, duration, t);
    osc.connect(gain).connect(this.sfx);
    osc.start(t);
    osc.stop(t + duration + 0.05);
  }

  private whoosh(duration: number, cutoff: number, volume: number): void {
    const ctx = this.ctx;
    if (!ctx) return;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(cutoff * 0.5, t);
    filter.frequency.exponentialRampToValueAtTime(cutoff * 1.6, t + duration);
    filter.Q.value = 1.2;
    const gain = ctx.createGain();
    this.envelope(gain, volume, duration, t);
    src.connect(filter).connect(gain).connect(this.sfx);
    src.start(t, Math.random() * 0.5);
    src.stop(t + duration + 0.05);
  }

  private thump(freq: number, volume: number, key: string): void {
    if (!this.ctx || this.throttled(key, 0.03)) return;
    this.tone(freq, freq * 0.4, 0.14, 'sine', volume);
    this.whoosh(0.06, 2500, volume * 0.5);
  }

  private chord(freqs: number[], duration: number, volume: number): void {
    for (const f of freqs) this.tone(f, f, duration, 'triangle', volume / freqs.length + 0.03);
  }

  private arpeggio(freqs: number[], step: number, volume: number): void {
    const ctx = this.ctx;
    if (!ctx) return;
    freqs.forEach((f, i) => {
      const t = ctx.currentTime + i * step;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = f;
      this.envelope(gain, volume, step * 3, t);
      osc.connect(gain).connect(this.sfx);
      osc.start(t);
      osc.stop(t + step * 3 + 0.05);
    });
  }

  /** Starts (or keeps) the ambient pad for a biome; `tense` adds a low pulse for boss fights. */
  playAmbience(biome: BiomeId, tense = false): void {
    const key = `${biome}:${tense}`;
    if (!this.ctx || this.ambienceKey === key) return;
    this.ambience?.stop();
    this.ambienceKey = key;
    const ctx = this.ctx;
    const root = BIOME_ROOTS[biome];
    const out = ctx.createGain();
    out.gain.value = 0;
    out.gain.linearRampToValueAtTime(1, ctx.currentTime + 2.5);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = tense ? 900 : 600;
    filter.connect(out).connect(this.music);

    // Two detuned drones with a slow filter sweep.
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 250;
    lfo.connect(lfoGain).connect(filter.frequency);
    lfo.start();
    const drones = [root / 2, (root / 2) * 1.5, root].map((f, i) => {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = i === 0 ? 'sine' : 'triangle';
      osc.frequency.value = f;
      osc.detune.value = (i - 1) * 6;
      g.gain.value = i === 0 ? 0.22 : 0.08;
      osc.connect(g).connect(filter);
      osc.start();
      return osc;
    });

    // Sparse bell notes drawn from the scale.
    const timer = window.setInterval(
      () => {
        if (!this.ctx) return;
        const t = ctx.currentTime;
        const f = root * 2 * SCALE[Math.floor(Math.random() * SCALE.length)] * (Math.random() < 0.3 ? 2 : 1);
        const osc = ctx.createOscillator();
        const g = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.value = f;
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(tense ? 0.05 : 0.07, t + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 2.4);
        osc.connect(g).connect(out);
        osc.start(t);
        osc.stop(t + 2.5);
      },
      tense ? 700 : 2200
    );

    this.ambience = {
      stop: () => {
        window.clearInterval(timer);
        const t = ctx.currentTime;
        out.gain.cancelScheduledValues(t);
        out.gain.setValueAtTime(out.gain.value, t);
        out.gain.linearRampToValueAtTime(0, t + 1.2);
        for (const o of [...drones, lfo]) o.stop(t + 1.3);
      },
    };
  }

  stopAmbience(): void {
    this.ambience?.stop();
    this.ambience = undefined;
    this.ambienceKey = '';
  }
}

/* Memory Reconstruction UI: a DOM layer over the canvas. */
:root {
  --ink: #e9e4f2;
  --ink-dim: #a69fb8;
  --gold: #ffd98a;
  --gold-deep: #c9973b;
  --cyan: #6fe7ff;
  --violet: #b89cff;
  --red: #ff4d5e;
  --panel: rgba(14, 12, 26, 0.86);
  --panel-edge: rgba(255, 217, 138, 0.28);
  --serif: 'Cinzel', Georgia, serif;
  --sans: 'Inter', system-ui, sans-serif;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  font-family: var(--sans);
  color: var(--ink);
  user-select: none;
  -webkit-user-select: none;
}
#ui .interactive,
#ui button {
  pointer-events: auto;
}

/* ---------- HUD ---------- */
.hud {
  position: absolute;
  inset: 0;
  transition: opacity 0.3s;
}
.hud.hidden {
  opacity: 0;
}
.hud-vitals {
  position: absolute;
  left: 20px;
  top: 18px;
  width: 280px;
  display: grid;
  gap: 6px;
}
.hud-level {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: 0.08em;
  color: var(--gold);
  text-shadow: 0 2px 6px #000;
}
.hud-level small {
  font-family: var(--sans);
  color: var(--ink-dim);
  font-size: 12px;
  letter-spacing: 0.04em;
}
.bar {
  position: relative;
  height: 16px;
  background: rgba(0, 0, 0, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}
.bar.thin {
  height: 5px;
  border-radius: 3px;
}
.bar-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  transition: width 0.12s ease-out;
}
.bar-lag {
  position: absolute;
  inset: 0 auto 0 0;
  background: rgba(255, 255, 255, 0.55);
  transition: width 0.6s ease-in 0.2s;
}
.bar.hp .bar-fill {
  background: linear-gradient(180deg, #ff7a86, #d92e44);
}
.bar.mana .bar-fill {
  background: linear-gradient(180deg, #9cf0ff, #2fa6d6);
}
.bar.xp .bar-fill {
  background: linear-gradient(90deg, var(--gold-deep), var(--gold));
}
.bar-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-shadow: 0 1px 2px #000, 0 0 4px #000;
}
.hud-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 2px;
  font-size: 13px;
  font-weight: 600;
  text-shadow: 0 1px 3px #000;
}
.pips {
  display: flex;
  gap: 4px;
}
.pip {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1.5px solid var(--cyan);
  background: transparent;
  position: relative;
  overflow: hidden;
}
.pip span {
  position: absolute;
  inset: auto 0 0 0;
  background: var(--cyan);
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.chip img {
