}
.boss-bar.hidden {
  opacity: 0;
}
.boss-name {
  font-family: var(--serif);
  font-size: 18px;
  letter-spacing: 0.14em;
  color: #ffd0d4;
  text-shadow: 0 2px 8px #000;
  margin-bottom: 4px;
}
.boss-bar .bar {
  height: 12px;
}
.boss-bar .bar-fill {
  background: linear-gradient(180deg, #ff6a7a, #a3162c);
}

.hud-map {
  position: absolute;
  right: 18px;
  top: 16px;
  display: grid;
  gap: 6px;
  justify-items: end;
}
.minimap {
  background: rgba(8, 7, 16, 0.72);
  border: 1px solid var(--panel-edge);
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5);
}
.hud-shards {
  font-size: 14px;
  font-weight: 700;
  color: var(--violet);
  text-shadow: 0 1px 3px #000;
}

.prompt {
  position: absolute;
  bottom: 18%;
  left: 50%;
  transform: translateX(-50%);
  padding: 8px 16px;
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-radius: 8px;
  font-size: 14px;
  white-space: nowrap;
  transition: opacity 0.2s;
}
.prompt.hidden {
  opacity: 0;
}

.toasts {
  position: absolute;
  top: 22%;
  left: 50%;
  transform: translateX(-50%);
  display: grid;
  gap: 8px;
  justify-items: center;
}
.toast {
  font-family: var(--serif);
  font-size: 20px;
  letter-spacing: 0.1em;
  color: var(--gold);
  text-shadow: 0 2px 10px #000, 0 0 2px #000;
  animation: toast 2.4s ease forwards;
  white-space: nowrap;
}
.toast.warn {
  color: #ffb3b3;
}
@keyframes toast {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  12%,
  75% {
    opacity: 1;
    transform: none;
  }
  100% {
    opacity: 0;
    transform: translateY(-6px);
  }
}

.hint {
  position: absolute;
  left: 20px;
  bottom: 16px;
  font-size: 12px;
  color: var(--ink-dim);
  line-height: 1.9;
  text-shadow: 0 1px 2px #000;
  transition: opacity 1s;
}
.hint.hidden {
  opacity: 0;
}

.lore {
  position: absolute;
  bottom: 9%;
  left: 50%;
  transform: translateX(-50%);
  width: min(560px, 86vw);
  padding: 16px 22px;
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-radius: 10px;
  text-align: center;
  animation: lore 7s ease forwards;
}
.lore h4 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 12px;
  letter-spacing: 0.22em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 8px;
}
.lore p {
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.5;
  font-style: italic;
}
@keyframes lore {
  0% {
    opacity: 0;
    transform: translate(-50%, 10px);
  }
  8%,
  85% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  100% {
    opacity: 0;
  }
}

