// Visits every depth and screenshots a combat room plus the map.
import { chromium } from 'playwright';
const out = process.argv[2] || '.';
const depths = (process.argv[3] || '0,1,2,3,4,5').split(',').map(Number);
const browser = await chromium.launch({ args: ['--use-gl=angle', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const logs = [];
page.on('console', (m) => { if (m.type() === 'error') logs.push(`[error] ${m.text().slice(0, 300)}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
await page.goto('http://localhost:3017/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__MR__, null, { timeout: 20000 });
await page.getByRole('button', { name: /Begin|New Run/ }).click();
await page.waitForTimeout(600);
for (const depth of depths) {
  await page.evaluate((d) => {
    const app = window.__MR__;
    app.run.depth = d;
    app.enterFloor();
    const w = app.world;
    w.player.health = 9999;
    const room = w.floor.rooms.filter((r) => r.kind === 'combat').sort((a, b) => b.w * b.h - a.w * a.h)[0] ?? w.floor.rooms[w.floor.bossRoom];
    w.player.x = (room.x + room.w / 2) * 32;
    w.player.y = (room.y + room.h / 2) * 32 + 40;
  }, depth);
  await page.mouse.move(760, 330);
  await page.waitForTimeout(3600);
  if ((await page.evaluate(() => window.__MR__.state)) === 'choice') await page.keyboard.press('Digit1');
  await page.screenshot({ path: `${out}/depth${depth}.png` });
}
console.log(logs.slice(0, 20).join('\n') || 'no errors');
await browser.close();

