// Headless balance bot: plays full runs and reports where they end.
import { roomCentrePx } from '/src/sim/dungeon';
import { NO_INPUT, type InputFrame } from '/src/sim/entities';
import { createRun } from '/src/sim/run';
import { TILE_SIZE } from '/src/sim/tiles';
import { World } from '/src/sim/world';
import { slamRadius } from '/src/sim/enemies';

const DT = 1 / 60;
const runs = Number(process.argv[2] ?? 20);
const skill = Number(process.argv[3] ?? 0.7); // chance to react to a telegraph

function path(world: World, tx: number, ty: number): Array<[number, number]> {
  const g = world.grid;
  const sx = Math.floor(world.player.x / TILE_SIZE);
  const sy = Math.floor(world.player.y / TILE_SIZE);
  const prev = new Map<number, number>();
  const start = g.index(sx, sy);
  const goal = g.index(tx, ty);
  const queue = [start];
  prev.set(start, -1);
  while (queue.length) {
    const cur = queue.shift()!;
    if (cur === goal) break;
    const cx = cur % g.width, cy = Math.floor(cur / g.width);
    for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
      const nx = cx + dx, ny = cy + dy;
      if (g.isSolid(nx, ny)) continue;
      const ni = g.index(nx, ny);
      if (prev.has(ni)) continue;
      prev.set(ni, cur);
      queue.push(ni);
    }
  }
  if (!prev.has(goal)) return [];
  const out: Array<[number, number]> = [];
  for (let c = goal; c !== -1 && c !== start; c = prev.get(c)!) out.push([c % g.width, Math.floor(c / g.width)]);
  return out.reverse();
}

function target(world: World): { x: number; y: number } | undefined {
  const p = world.player;
  const portal = world.interactables.find((i) => i.kind === 'portal');
  const frag = world.pickups.find((i) => i.kind === 'fragment');
  if (frag) return frag;
  const chest = world.interactables.find((i) => i.kind === 'chest' && !i.used);
  if (chest) return chest;
  const unvisited = world.floor.rooms.filter((r) => !world.visited[r.id] && r.kind !== 'boss');
  if (unvisited.length) {
    unvisited.sort((a, b) => Math.hypot(roomCentrePx(a).x - p.x, roomCentrePx(a).y - p.y) - Math.hypot(roomCentrePx(b).x - p.x, roomCentrePx(b).y - p.y));
    return roomCentrePx(unvisited[0]);
  }
  if (portal) return portal;
  return roomCentrePx(world.floor.rooms[world.floor.bossRoom]);
}

let rngState = 12345;
const rand = () => ((rngState = (rngState * 1103515245 + 12345) >>> 0) / 4294967296);

function decide(world: World, cache: { path: Array<[number, number]>; goalKey: string; stuck: number }): InputFrame {
  const p = world.player;
  const input: InputFrame = { ...NO_INPUT, aimX: p.x + 1, aimY: p.y };
  if (p.health < p.stats.maxHealth * 0.35 && p.potions > 0) input.potion = true;
  const enemies = world.enemies.filter((e) => e.state !== 'dying' && e.state !== 'spawning');
  // Dodge telegraphed attacks that would reach us.
  for (const e of enemies) {
    if (e.state !== 'windup' || e.stateTime > 0.2) continue;
    const d = Math.hypot(e.x - p.x, e.y - p.y);
    const reach = e.attack === 'slam' ? slamRadius(e) + 20 : e.attack === 'charge' ? 340 : e.attack === 'lunge' ? 160 : e.attack === 'strike' ? e.def.attackRange + 40 : 0;
    if (d < reach && rand() < skill * 0.15) {
      input.dash = true;
      input.moveX = -(e.y - p.y) / d;
      input.moveY = (e.x - p.x) / d;
      return input;
    }
  }
  // Enemy projectiles about to hit: sidestep.
  for (const b of world.projectiles) {
    if (b.owner !== 'enemy') continue;
    const d = Math.hypot(b.x - p.x, b.y - p.y);
    if (d < 50 && rand() < skill * 0.08) {
      input.dash = true;
      input.moveX = -b.vy; input.moveY = b.vx;
      return input;
    }
  }
  if (enemies.length) {
    const e = enemies.sort((a, b) => Math.hypot(a.x - p.x, a.y - p.y) - Math.hypot(b.x - p.x, b.y - p.y))[0];
    const d = Math.hypot(e.x - p.x, e.y - p.y);
    input.aimX = e.x; input.aimY = e.y;
    if (d > 44 + e.radius) { input.moveX = e.x - p.x; input.moveY = e.y - p.y; }
    if (d < 70 + e.radius) input.attack = true;
    if (d > 140 && p.mana > p.stats.boltCost + 10) input.bolt = true;
    return input;
  }
  const t = target(world);
  if (!t) return input;
  const near = world.nearbyInteractable();
  if (near && near.kind === 'chest') input.interact = true;
  if (near && near.kind === 'shrine' && p.shards >= near.cost) input.interact = true;
  const tx = Math.floor(t.x / TILE_SIZE), ty = Math.floor(t.y / TILE_SIZE);
  const key = `${tx},${ty}`;
  if (cache.goalKey !== key || cache.path.length === 0 || cache.stuck > 30) {
    cache.path = path(world, tx, ty); cache.goalKey = key; cache.stuck = 0;
  }
  while (cache.path.length) {
    const [nx, ny] = cache.path[0];
    const wx = (nx + 0.5) * TILE_SIZE, wy = (ny + 0.5) * TILE_SIZE;
    if (Math.hypot(wx - p.x, wy - p.y) < 10) { cache.path.shift(); continue; }
    input.moveX = wx - p.x; input.moveY = wy - p.y;
    break;
  }
  if (!cache.path.length) { input.moveX = t.x - p.x; input.moveY = t.y - p.y; }
  // Also visit shrines when rich.
  const shrine = world.interactables.find((i) => i.kind === 'shrine' && !i.used && p.shards >= i.cost);
  if (shrine && Math.hypot(shrine.x - p.x, shrine.y - p.y) < 300) { input.moveX = shrine.x - p.x; input.moveY = shrine.y - p.y; }
  return input;
}

const results: Array<{ depth: number; won: boolean; level: number; time: number; kills: number; floorLevels: number[]; cause: string }> = [];
for (let r = 0; r < runs; r++) {
  const run = createRun(1000 + r * 7919, []);
  const floorLevels: number[] = [];
  let won = false;
  let cause = '';
  outer: for (;;) {
    const world = new World(run);
    floorLevels.push(run.player.level);
    const cache = { path: [] as Array<[number, number]>, goalKey: '', stuck: 0 };
    let lastHitBy = '';
    for (let frame = 0; frame < 60 * 60 * 8; frame++) {
      while (world.awaitingChoice) world.chooseUpgrade(world.run.pendingChoices[0].options[0] ?? '');
      const hpBefore = world.player.health;
      const events = world.step(decide(world, cache), DT);
      if (world.player.health < hpBefore) {
        const near = world.enemies.filter((e) => e.state !== 'dying').sort((a, b) => Math.hypot(a.x - world.player.x, a.y - world.player.y) - Math.hypot(b.x - world.player.x, b.y - world.player.y))[0];
        lastHitBy = near ? `${near.def.id}${near.isBoss ? '(boss)' : ''}` : '?';
      }
      if (events.some((e) => e.type === 'playerDied')) { cause = lastHitBy; break outer; }
      if (world.victory) { won = true; break outer; }
      if (world.exited) { run.depth++; continue outer; }
    }
    cause = 'timeout';
    break;
  }
  results.push({ depth: run.depth, won, level: run.player.level, time: Math.round(run.stats.elapsed), kills: run.stats.kills, floorLevels, cause });
}
const byDepth = new Map<number, number>();
for (const r of results) byDepth.set(r.depth, (byDepth.get(r.depth) ?? 0) + 1);
console.log('ended at depth:', JSON.stringify(Object.fromEntries([...byDepth].sort())), 'wins:', results.filter((r) => r.won).length, '/', runs);
const causes = new Map<string, number>();
for (const r of results) causes.set(`${r.depth}:${r.cause}`, (causes.get(`${r.depth}:${r.cause}`) ?? 0) + 1);
console.log('causes:', JSON.stringify(Object.fromEntries(causes)));
for (const r of results.slice(0, 8)) console.log(JSON.stringify(r));

