// End-to-end check of flows not covered by play2: chest, portal, death, continue, memories, settings, victory.
import { chromium } from 'playwright';
const out = process.argv[2] || '.';
const browser = await chromium.launch({ args: ['--use-gl=angle', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const logs = [];
page.on('console', (m) => { if (m.type() === 'error') logs.push(`[error] ${m.text().slice(0, 300)}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
const shot = (n) => page.screenshot({ path: `${out}/${n}.png` });
const state = () => page.evaluate(() => window.__MR__.state);
const check = (label, ok) => console.log(`${ok ? 'PASS' : 'FAIL'} ${label}`);

await page.goto('http://localhost:3017/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.__MR__, null, { timeout: 20000 });
await page.getByRole('button', { name: /Begin/ }).click();
await page.waitForTimeout(500);

// Chest: walk next to it and press E.
await page.evaluate(() => {
  const w = window.__MR__.world;
  const chest = w.interactables.find((i) => i.kind === 'chest');
  w.player.x = chest.x; w.player.y = chest.y + 26;
});
await page.waitForTimeout(300);
await shot('01_chest_prompt');
await page.keyboard.press('KeyE');
await page.waitForTimeout(500);
check('chest opens a choice', (await state()) === 'choice');
await shot('02_chest_choice');
await page.keyboard.press('Digit1');
await page.waitForTimeout(300);
// Pick up the fragment the chest dropped.
await page.evaluate(() => {
  const w = window.__MR__.world;
  const f = w.pickups.find((p) => p.kind === 'fragment');
  if (f) { w.player.x = f.x; w.player.y = f.y; }
});
await page.waitForTimeout(600);
await shot('03_fragment');
check('fragment saved to meta', await page.evaluate(() => JSON.parse(localStorage.getItem('memory-reconstruction.meta.v1')).fragments.length === 1));

// Boss: kill it, then use the rift.
await page.evaluate(() => {
  const w = window.__MR__.world;
  const room = w.floor.rooms[w.floor.bossRoom];
  w.player.x = (room.x + room.w / 2) * 32; w.player.y = (room.y + room.h / 2 + 3) * 32;
});
await page.waitForTimeout(2200);
await page.evaluate(() => { const w = window.__MR__.world; const b = w.activeBoss(); if (b) { b.state = 'chase'; w.damageEnemy(b, 1e6, 'melee', false, 0); } });
await page.waitForTimeout(1500);
while ((await state()) === 'choice') { await page.keyboard.press('Digit1'); await page.waitForTimeout(250); }
await page.evaluate(() => { const w = window.__MR__.world; const p = w.interactables.find((i) => i.kind === 'portal'); w.player.x = p.x; w.player.y = p.y + 10; });
await page.waitForTimeout(400);
await shot('04_rift_prompt');
await page.keyboard.press('KeyE');
await page.waitForTimeout(1200);
check('rift leads to depth 2', await page.evaluate(() => window.__MR__.world.run.depth === 1));
await shot('05_depth2_banner');

// Reload and continue.
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.__MR__, null, { timeout: 20000 });
await page.waitForTimeout(500);
await shot('06_title_continue');
await page.getByRole('button', { name: 'Continue' }).click();
await page.waitForTimeout(800);
check('continue resumes at depth 2', await page.evaluate(() => window.__MR__.state === 'playing' && window.__MR__.world.run.depth === 1));

// Death.
await page.evaluate(() => { const w = window.__MR__.world; w.player.invulnerable = 0; w.damagePlayer(9999, w.player.x + 5, w.player.y, 0); });
await page.waitForTimeout(2200);
check('death screen', (await state()) === 'dead');
await shot('07_death');
check('run save cleared after death', await page.evaluate(() => localStorage.getItem('memory-reconstruction.run.v1') === null));
await page.getByRole('button', { name: 'Title' }).click();
await page.waitForTimeout(500);
await page.getByRole('button', { name: /Memories/ }).click();
await page.waitForTimeout(400);
await shot('08_memories');
await page.getByRole('button', { name: 'Back' }).click();
await page.getByRole('button', { name: 'Settings' }).click();
await page.waitForTimeout(300);
await shot('09_settings');
await page.getByRole('button', { name: 'Back' }).click();

// Victory: jump to the final floor and defeat the Keeper.
await page.getByRole('button', { name: /New Run/ }).click();
await page.waitForTimeout(400);
await page.evaluate(() => {
  const app = window.__MR__; app.run.depth = 5; app.enterFloor();
  const w = app.world; const room = w.floor.rooms[w.floor.bossRoom];
  w.player.x = (room.x + room.w / 2) * 32; w.player.y = (room.y + room.h / 2 + 3) * 32;
});
await page.waitForTimeout(2600);
await shot('10_keeper');
await page.evaluate(() => { const w = window.__MR__.world; const b = w.activeBoss(); b.state = 'chase'; w.damageEnemy(b, 1e7, 'melee', false, 0); });
await page.waitForTimeout(500);
while ((await state()) === 'choice') { await page.keyboard.press('Digit1'); await page.waitForTimeout(250); }
await page.waitForTimeout(3500);
check('victory screen', (await state()) === 'victory');
await shot('11_victory');
console.log(logs.slice(0, 20).join('\n') || 'no console errors');
await browser.close();

